###############################################################################
# DRS managed policy equivalents (provisioned in-account so the stack is
# self-contained and deployable without pre-existing AWS-managed policies)
###############################################################################

data "aws_iam_policy_document" "drs_agent_policy" {
  statement {
    sid    = "DrsAgentPolicy"
    effect = "Allow"

    actions = [
      "drs:SendAgentMetricsForDrs",
      "drs:SendAgentLogsForDrs",
      "drs:UpdateAgentSourcePropertiesForDrs",
      "drs:UpdateAgentReplicationInfoForDrs",
      "drs:UpdateAgentConversionInfoForDrs",
      "drs:GetAgentInstallationAssetsForDrs",
      "drs:CheckForReplicationConfiguration",
      "drs:SendClientLogsForDrs",
      "drs:SendClientMetricsForDrs",
      "drs:RegisterClientForDrs",
      "drs:TagResource",
      "drs:IssueAgentCertificateForDrs",
      "drs:DescribeSourceServers",
      "drs:DescribeRecoveryInstances",
      "drs:DescribeRecoverySnapshots",
      "drs:DescribeReplicationConfigurationTemplates",
      "drs:DescribeJobs",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DrsAgentPolicyCloudWatch"
    effect = "Allow"

    actions = [
      "cloudwatch:PutMetricData",
      "cloudwatch:GetMetricData",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DrsAgentPolicyEC2"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
      "ec2:CreateVolume",
      "ec2:AttachVolume",
      "ec2:DeleteVolume",
      "ec2:CreateTags",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "drs_agent_policy" {
  name        = "AWSElasticDisasterRecoveryAgentPolicy"
  path        = "/"
  description = "Permissions for the AWS Elastic Disaster Recovery agent."
  policy      = data.aws_iam_policy_document.drs_agent_policy.json
  tags        = local.tags
}

data "aws_iam_policy_document" "drs_failback_policy" {
  statement {
    sid    = "DrsFailbackPolicy"
    effect = "Allow"

    actions = [
      "drs:SendFailbackLogs",
      "drs:SendFailbackMetrics",
      "drs:UpdateFailbackClientCapacityForDrs",
      "drs:UpdateFailbackClientLastSeenForDrs",
      "drs:StartFailback",
      "drs:FinalizeFailback",
      "drs:DescribeFailbackJobs",
      "drs:TagResource",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "drs_failback_policy" {
  name        = "AWSElasticDisasterRecoveryFailbackPolicy"
  path        = "/"
  description = "Permissions for the AWS Elastic Disaster Recovery failback client."
  policy      = data.aws_iam_policy_document.drs_failback_policy.json
