}

data "aws_iam_policy_document" "drs_conversion_server_policy" {
  statement {
    sid    = "DrsConversionServerPolicy"
    effect = "Allow"

    actions = [
      "drs:SendAgentMetricsForDrs",
      "drs:SendAgentLogsForDrs",
      "drs:UpdateAgentConversionInfoForDrs",
      "drs:GetAgentInstallationAssetsForDrs",
      "drs:RegisterClientForDrs",
      "drs:IssueAgentCertificateForDrs",
      "drs:TagResource",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "drs_conversion_server_policy" {
  name        = "AWSElasticDisasterRecoveryConversionServerPolicy"
  path        = "/"
  description = "Permissions for the AWS Elastic Disaster Recovery conversion server."
  policy      = data.aws_iam_policy_document.drs_conversion_server_policy.json
  tags        = local.tags
}

data "aws_iam_policy_document" "drs_recovery_instance_policy" {
  statement {
    sid    = "DrsRecoveryInstancePolicy"
    effect = "Allow"

    actions = [
      "drs:SendAgentMetricsForDrs",
      "drs:SendAgentLogsForDrs",
      "drs:UpdateAgentSourcePropertiesForDrs",
      "drs:UpdateAgentReplicationInfoForDrs",
      "drs:UpdateAgentConversionInfoForDrs",
      "drs:GetAgentInstallationAssetsForDrs",
      "drs:RegisterClientForDrs",
      "drs:SendClientLogsForDrs",
      "drs:SendClientMetricsForDrs",
      "drs:IssueAgentCertificateForDrs",
      "drs:DescribeReplicationConfigurationTemplates",
      "drs:TagResource",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DrsRecoveryInstancePolicyEC2"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeTags",
      "ec2:CreateTags",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "drs_recovery_instance_policy" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
  path        = "/"
  description = "Permissions for AWS Elastic Disaster Recovery recovery instances."
  policy      = data.aws_iam_policy_document.drs_recovery_instance_policy.json
  tags        = local.tags
