data "aws_iam_policy_document" "drs_replication_server_policy" {
  statement {
    sid    = "DrsReplicationServerPolicy"
    effect = "Allow"

    actions = [
      "drs:SendAgentMetricsForDrs",
      "drs:SendAgentLogsForDrs",
      "drs:UpdateAgentReplicationInfoForDrs",
      "drs:GetAgentInstallationAssetsForDrs",
      "drs:IssueAgentCertificateForDrs",
      "drs:RegisterClientForDrs",
      "drs:TagResource",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DrsReplicationServerPolicyEC2"
    effect = "Allow"

    actions = [
      "ec2:CreateSnapshot",
