###############################################################################
# Initializer role (root path)
###############################################################################

resource "aws_iam_role" "initializer" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  description        = "Initializer role used to bootstrap AWS Elastic Disaster Recovery."
  assume_role_policy = data.aws_iam_policy_document.initializer_assume_role.json
  tags               = local.tags
}

###############################################################################
# InitializePolicy
###############################################################################

data "aws_iam_policy_document" "initialize_policy" {
  statement {
    sid       = "DRSInitializeService"
    effect    = "Allow"
    actions   = ["drs:InitializeService"]
    resources = ["*"]
  }

  statement {
    sid    = "InstanceProfileLifecycle"
    effect = "Allow"

    actions = [
      "iam:CreateInstanceProfile",
      "iam:DeleteInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:ListInstanceProfilesForRole",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:instance-profile/*",
    ]
  }

  statement {
    sid    = "PassDRSServiceRoles"
    effect = "Allow"

    actions = ["iam:PassRole"]

    resources = [
      aws_iam_role.agent.arn,
      aws_iam_role.failback.arn,
      aws_iam_role.conversion_server.arn,
      aws_iam_role.recovery_instance.arn,
      aws_iam_role.replication_server.arn,
      aws_iam_role.recovery_instance_with_launch_actions.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values = [
        "ec2.amazonaws.com",
        "drs.amazonaws.com",
      ]
    }
  }

  statement {
    sid    = "CreateDRSServiceLinkedRole"
    effect = "Allow"

    actions = ["iam:CreateServiceLinkedRole"]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery",
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  statement {
    sid       = "EC2FullAccessForInitialization"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AttachDetachDRSManagedPolicies"
    effect = "Allow"

    actions = [
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy",
    ]

    resources = [
      aws_iam_role.agent.arn,
      aws_iam_role.failback.arn,
      aws_iam_role.conversion_server.arn,
      aws_iam_role.recovery_instance.arn,
      aws_iam_role.replication_server.arn,
      aws_iam_role.recovery_instance_with_launch_actions.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PolicyARN"
      values   = local.drs_managed_policy_arns
    }
  }
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  description = "Permissions required to initialize and bootstrap AWS Elastic Disaster Recovery."
  policy      = data.aws_iam_policy_document.initialize_policy.json
  tags        = local.tags
}

resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

