###############################################################################
# Input variables
###############################################################################

variable "prefix" {
  description = "Prefix applied to every resource created by this stack."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ACM certificate ARN used by the HTTPS listener. When null a self-signed certificate is generated and imported."
  type        = string
  default     = null
}

variable "url" {
  description = "Public URL exposed through WEBHOOK_URL. When null the ALB HTTPS endpoint is used."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Number of n8n tasks to run."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider used by the cluster and the service."
  type        = string
  default     = "FARGATE_SPOT"
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  azs                  = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  container_name = "n8n"
  container_port = 5678

  certificate_arn = var.certificate_arn != null ? var.certificate_arn : one(aws_acm_certificate.self_signed[*].arn)
  webhook_url     = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
}

###############################################################################
# Network
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-private-${count.index + 1}"
    Tier = "private"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-public-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.prefix}-public"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-private"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb"
  description = "HTTP/HTTPS entry point for the n8n load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward traffic to the n8n tasks only"
    from_port   = local.container_port
    to_port     = local.container_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs"
  description = "NFS access to the n8n EFS file system from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from the VPC CIDR only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-efs"
  }
}

resource "aws_security_group" "tasks" {
  name        = "${var.prefix}-tasks"
  description = "n8n tasks reachable only from the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Container port from the ALB security group"
    from_port       = local.container_port
    to_port         = local.container_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-tasks"
  }
}

###############################################################################
# Self-signed certificate (used when no certificate_arn is supplied)
###############################################################################

resource "tls_private_key" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = "${var.prefix}.local"
    organization = "n8n"
  }

  validity_period_hours = 8760
  early_renewal_hours   = 720

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]

  dns_names = ["${var.prefix}.local"]
}

resource "aws_acm_certificate" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  tags = {
    Name = "${var.prefix}-self-signed"
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Application Load Balancer
###############################################################################

resource "aws_lb" "main" {
  name               = "${var.prefix}-alb"
  internal           = true
  load_balancer_type = "application"

  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_lb_target_group" "n8n" {
  name        = "${var.prefix}-tg"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  protocol    = "HTTP"
  port        = 80

  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/healthz"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${var.prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }

  tags = {
    Name = "${var.prefix}-https"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol    = "HTTPS"
      port        = "443"
      status_code = "HTTP_301"
    }
  }

  tags = {
    Name = "${var.prefix}-http"
  }
}

###############################################################################
# Persistent storage (EFS)
###############################################################################

resource "aws_efs_file_system" "n8n" {
  encrypted = true

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = {
    Name = "${var.prefix}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "n8n" {
  count = 3

  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# Logging
###############################################################################

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${var.prefix}-logs"
  }
}

###############################################################################
# Secrets
###############################################################################

resource "tls_private_key" "encryption_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_secretsmanager_secret" "n8n" {
  name                    = "${var.prefix}-encryption-key"
  description             = "n8n encryption key used to encrypt stored credentials"
  recovery_window_in_days = 0

  tags = {
    Name = "${var.prefix}-encryption-key"
  }
}

resource "aws_secretsmanager_secret_version" "n8n" {
  secret_id     = aws_secretsmanager_secret.n8n.id
  secret_string = tls_private_key.encryption_key.private_key_pem
}

###############################################################################
# IAM
###############################################################################

resource "aws_iam_role" "ecs_task_execution" {
  name = "${var.prefix}-ecs-task-execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.prefix}-ecs-task-execution"
  }
}

resource "aws_iam_role_policy" "ecs_task_execution" {
  name = "${var.prefix}-ecs-task-execution"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          aws_secretsmanager_secret.n8n.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task" {
  name = "${var.prefix}-ecs-task"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.prefix}-ecs-task"
  }
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${var.prefix}-ecs-task"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = [
          aws_efs_file_system.n8n.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      }
    ]
  })
}

###############################################################################
# ECS cluster
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name = aws_ecs_cluster.main.name

  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

###############################################################################
# ECS task definition
###############################################################################

resource "aws_ecs_task_definition" "n8n" {
  family                   = "${var.prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }

  volume {
    name = "n8n-efs"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      root_directory     = "/"
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true
      user      = "1000"

      portMappings = [
        {
          containerPort = local.container_port
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-efs"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      secrets = [
        {
          name      = "N8N_ENCRYPTION_KEY"
          valueFrom = aws_secretsmanager_secret.n8n.arn
        }
      ]

      linuxParameters = {
        initProcessEnabled = true
      }

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.prefix
          "mode"                  = "non-blocking"
        }
      }
    }
  ])

  tags = {
    Name = "${var.prefix}-task"
  }
}

###############################################################################
# ECS service
###############################################################################

resource "aws_ecs_service" "n8n" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count
  propagate_tags  = "SERVICE"

  health_check_grace_period_seconds = 60

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = local.container_name
    container_port   = local.container_port
  }

  depends_on = [
    aws_lb_listener.https,
    aws_efs_mount_target.n8n,
  ]

  tags = {
    Name = "${var.prefix}-service"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.255.0.0/16"

  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.255.100.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.255.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_route_table_association" "rds_1a" {
  subnet_id      = aws_subnet.rds_1a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "rds_1e" {
  subnet_id      = aws_subnet.rds_1e.id
  route_table_id = aws_route_table.public.id
}

resource "aws_db_subnet_group" "rds" {
  name       = "quasar-rds"
  subnet_ids = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host access - SSH from the administrative CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from administrative CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA Proxy - HTTP/HTTPS from the internet, SSH from the bastion"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD - SSH from the bastion, UI traffic from the proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI from the HA proxy security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes - SSH from the bastion and Jenkins"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from the Jenkins security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgres" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database access for the data stack"
  vpc_id      = aws_vpc.main.id

  # NOTE: The 0.0.0.0/0 ingress on tcp/5432 is an explicit user requirement.
  # This rule is world-open and should be narrowed to VPC/peer-security-group
  # ranges before production use.
  ingress {
    description = "PostgreSQL from anywhere (explicit requirement - narrow before production)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from the ETL security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

data "aws_partition" "current" {}

########################################################################
# Input variables
########################################################################

variable "create" {
  description = "Global switch that gates creation of every CodeDeploy resource in this configuration."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function participating in the blue/green deployment."
  type        = string
  default     = "my-lambda-function"
}

variable "alias_name" {
  description = "Name of the Lambda alias used for blue/green traffic shifting."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Currently deployed Lambda version (blue)."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Lambda version that will be deployed (green)."
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked before traffic is shifted to the target version."
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked after traffic is shifted to the target version."
  type        = string
  default     = null
}

variable "create_app" {
  description = "Create a new CodeDeploy application when true."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Re-use an existing CodeDeploy application named by app_name when true."
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of the CodeDeploy application."
  type        = string
  default     = "lambda-blue-green-app"
}

variable "create_deployment_group" {
  description = "Create a new CodeDeploy deployment group when true."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Re-use an existing deployment group named by deployment_group_name when true."
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  type        = string
  default     = "lambda-blue-green-dg"
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration used by the deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  description = "Enable automatic rollback on the deployment group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "Deployment events that trigger an automatic rollback."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "cloudwatch_alarms" {
  description = "Optional list of CloudWatch alarm names monitored by the deployment group."
  type        = list(string)
  default     = []
}

variable "alarm_enabled" {
  description = "Enable CloudWatch alarm monitoring on the deployment group."
  type        = bool
  default     = true
}

variable "ignore_poll_alarm_failure" {
  description = "Continue the deployment when CloudWatch alarm polling fails."
  type        = bool
  default     = false
}

variable "trigger_name" {
  description = "Optional name of the SNS notification trigger."
  type        = string
  default     = null
}

variable "trigger_target_arn" {
  description = "Optional SNS topic ARN targeted by the deployment group trigger."
  type        = string
  default     = null
}

variable "trigger_events" {
  description = "Deployment events that publish to the trigger SNS topic."
  type        = list(string)
  default     = []
}

variable "create_codedeploy_role" {
  description = "Create the IAM service role used by CodeDeploy when true."
  type        = bool
  default     = true
}

variable "existing_codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy service role used when create_codedeploy_role is false."
  type        = string
  default     = null
}

variable "codedeploy_role_name" {
  description = "Optional explicit name for the CodeDeploy IAM role."
  type        = string
  default     = null
}

variable "service_principals" {
  description = "Service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Attach the inline lambda:InvokeFunction policy for lifecycle hooks when true."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Attach the inline sns:Publish policy for deployment triggers when true."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Generate the AppSpec revision and deployment shell script when true."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI executable used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between get-deployment status polls."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Poll the deployment status until it reaches a terminal state."
  type        = bool
  default     = true
}

variable "save_deploy_script" {
  description = "Persist the generated deployment script locally when true."
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Execute the generated deployment script through a null_resource when true."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Optional list of tokens used to trigger a fresh deployment run."
  type        = list(string)
  default     = []
}

########################################################################
# Locals: resolved names, AppSpec revision and deployment script
########################################################################

locals {
  app_name = var.create_app && !var.use_existing_app ? one(aws_codedeploy_app.this[*].name) : var.app_name

  deployment_group_name = var.create_deployment_group && !var.use_existing_deployment_group ? one(aws_codedeploy_deployment_group.this[*].deployment_group_name) : var.deployment_group_name

  codedeploy_role_arn  = var.create_codedeploy_role ? one(aws_iam_role.codedeploy[*].arn) : var.existing_codedeploy_role_arn
  codedeploy_role_name = var.codedeploy_role_name != null ? var.codedeploy_role_name : "${var.app_name}-codedeploy-role"

  script_path = "${path.module}/deploy.sh"

  appspec = {
    version = var.current_version
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = merge(
            {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = var.current_version
              TargetVersion  = var.target_version
            },
            var.before_allow_traffic_hook_arn != null ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
            var.after_allow_traffic_hook_arn != null ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {},
          )
        }
      },
    ]
  }

  appspec_json = jsonencode(local.appspec)

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_json
    }
  })

  monitor_script = <<EOT
while true; do
  STATUS="$(${var.aws_cli_command} deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)"
  echo "Deployment status: $STATUS"
  case "$STATUS" in
    Succeeded)
      echo "Deployment completed successfully."
      break
      ;;
    Failed|Stopped)
      echo "Deployment did not complete successfully." >&2
      exit 1
      ;;
  esac
  sleep ${var.get_deployment_sleep_timer}
done
EOT

  monitor_block = var.monitor_deployment ? local.monitor_script : ""

  deploy_script = <<EOT
#!/usr/bin/env bash
set -euo pipefail

APP_NAME="${local.app_name}"
DEPLOYMENT_GROUP_NAME="${local.deployment_group_name}"

REVISION='${local.revision_json}'

DEPLOYMENT_ID="$(${var.aws_cli_command} deploy create-deployment \
  --application-name "$APP_NAME" \
  --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
  --revision "$REVISION" \
  --query 'deploymentId' \
  --output text)"

echo "Created CodeDeploy deployment: $DEPLOYMENT_ID"

${local.monitor_block}
EOT
}

########################################################################
# CodeDeploy application
########################################################################

resource "aws_codedeploy_app" "this" {
  count = var.create && var.create_app && !var.use_existing_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"
}

########################################################################
# IAM role for CodeDeploy
########################################################################

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name = local.codedeploy_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = var.service_principals
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

resource "aws_iam_role_policy" "codedeploy_hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (var.before_allow_traffic_hook_arn != null || var.after_allow_traffic_hook_arn != null) ? 1 : 0

  name = "${local.codedeploy_role_name}-hooks"
  role = aws_iam_role.codedeploy[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn])
      }
    ]
  })
}

resource "aws_iam_role_policy" "codedeploy_triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && var.trigger_target_arn != null ? 1 : 0

  name = "${local.codedeploy_role_name}-triggers"
  role = aws_iam_role.codedeploy[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = [var.trigger_target_arn]
      }
    ]
  })
}

########################################################################
# CodeDeploy deployment group (Lambda blue/green)
########################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = length(var.cloudwatch_alarms) > 0 ? [1] : []

    content {
      enabled                   = var.alarm_enabled
      alarms                    = var.cloudwatch_alarms
      ignore_poll_alarm_failure = var.ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_target_arn != null ? [1] : []

    content {
      trigger_name       = var.trigger_name
      trigger_target_arn = var.trigger_target_arn
      trigger_events     = var.trigger_events
    }
  }
}

########################################################################
# Generated deployment script (optional persistence) and execution
########################################################################

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  filename        = local.script_path
  content         = local.deploy_script
  file_permission = "0755"
}

resource "null_resource" "run_deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    deploy_token          = length(var.force_deploy) > 0 ? join("-", [for f in var.force_deploy : tostring(f)]) : uuid()
    app_name              = local.app_name
    deployment_group_name = local.deployment_group_name
    revision_hash         = sha256(local.revision_json)
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]

    command = <<EOT
set -euo pipefail
SCRIPT_FILE="$(mktemp)"
cat > "$SCRIPT_FILE" <<'DEPLOY_SCRIPT_EOF'
${local.deploy_script}
DEPLOY_SCRIPT_EOF
chmod +x "$SCRIPT_FILE"
bash "$SCRIPT_FILE"
EOT
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "internal_domain" {
  description = "Internal DNS domain name used for DHCP options and the private Route 53 hosted zone."
  type        = string
  default     = "internal"
}

variable "admin_cidrs" {
  description = "List of CIDR blocks permitted to SSH into the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "environment" {
  description = "Environment identifier applied to all resource tags."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "ig"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = ["AmazonProvidedDNS", "8.8.8.8"]

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "main" {
  name          = var.internal_domain
  comment       = "Private hosted zone for the ${var.internal_domain} internal domain"
  force_destroy = false

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_subnet" "subnet_reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "reserved"
  })
}

resource "aws_subnet" "subnet_sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_subnet" "subnet_web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

resource "aws_subnet" "subnet_database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[3]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

resource "aws_subnet" "subnet_gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/22"
  availability_zone       = data.aws_availability_zones.available.names[4]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

resource "aws_route_table" "route_table_reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "reserved"
  })
}

resource "aws_route_table_association" "route_table_reserved_association" {
  subnet_id      = aws_subnet.subnet_reserved.id
  route_table_id = aws_route_table.route_table_reserved.id
}

resource "aws_route_table" "route_table_sandbox" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_route_table_association" "route_table_sandbox_association" {
  subnet_id      = aws_subnet.subnet_sandbox.id
  route_table_id = aws_route_table.route_table_sandbox.id
}

resource "aws_route_table" "route_table_web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

resource "aws_route_table_association" "route_table_web_association" {
  subnet_id      = aws_subnet.subnet_web.id
  route_table_id = aws_route_table.route_table_web.id
}

resource "aws_route_table" "route_table_database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

resource "aws_route_table_association" "route_table_database_association" {
  subnet_id      = aws_subnet.subnet_database.id
  route_table_id = aws_route_table.route_table_database.id
}

resource "aws_route_table" "route_table_gameserver" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

resource "aws_route_table_association" "route_table_gameserver_association" {
  subnet_id      = aws_subnet.subnet_gameserver.id
  route_table_id = aws_route_table.route_table_gameserver.id
}

resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.subnet_sandbox.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.subnet_web.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
