    cidr_block = aws_subnet.subnet_web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = aws_subnet.subnet_gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
