resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.subnet_gameserver.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    rule_no    = 120
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    rule_no    = 140
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    rule_no    = 150
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  ingress {
    rule_no    = 160
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH access from configured admin CIDRs and from members of this group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restrict outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Home SSH"
  })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH access from within the VPC and from members of this group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restrict outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Packer SSH"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Data sources (static / provider metadata lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

###############################################################################
# Variables
###############################################################################

variable "base_bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the current AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Append a short random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Additional bucket policy JSON documents merged into the enforced policy."
  type        = list(string)
  default     = []
}

variable "enable_s3_public_access_block" {
  description = "Enable the S3 public access block on the bucket."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "kms_master_key_id" {
  description = "KMS key ARN/ID used for SSE-KMS encryption. When null, AES256 is used."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status for the bucket (Enabled, Suspended, Disabled)."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Force destroy the bucket even when it contains objects."
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable S3 storage class analytics export to the same bucket."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable S3 bucket inventory reports to the same bucket."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Name of an external bucket that receives access logs. When null, logging is disabled."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled or Suspended). When null, acceleration is not configured."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL applied to the bucket. When null, no ACL resource is created."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to all resources created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Random suffix
###############################################################################

resource "random_id" "suffix" {
  count = var.use_random_suffix ? 1 : 0

  byte_length = 2
}

###############################################################################
# Locals
###############################################################################

locals {
  account_alias_raw = var.use_account_alias_prefix && length(data.aws_iam_account_alias.current) > 0 ? data.aws_iam_account_alias.current[0].account_alias : ""

  account_alias_prefix = local.account_alias_raw != "" ? trim(
    replace(lower(local.account_alias_raw), "/[^a-z0-9-]+/", "-"),
    "-"
  ) : ""

  random_suffix = var.use_random_suffix ? random_id.suffix[0].hex : ""

  bucket_name = join("-", compact([
    local.account_alias_prefix,
    lower(var.base_bucket_name),
    local.random_suffix,
  ]))

  common_tags = merge(var.tags, {
    Name = local.bucket_name
  })
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "default-lifecycle"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "analytics-export-retention"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "inventory-report-retention"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "entire-bucket-analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket                   = aws_s3_bucket.this.id
  name                     = "entire-bucket-inventory"
  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "ORC"
      prefix     = "_AWSBucketInventory/"
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Bucket policy (enforced compliance statements + custom policy merge)
###############################################################################

data "aws_iam_policy_document" "this" {
  source_policy_documents = var.custom_bucket_policy

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3InventoryAndAnalyticsWrites"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl",
    ]

    resources = [
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The name (ID) of the created S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the created S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_region" {
  description = "The AWS region the bucket resides in."
  value       = data.aws_region.current.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  use_name    = var.name != null && var.name != ""
  bucket_name = local.use_name ? var.name : (var.name_prefix != null ? var.name_prefix : "enterprise-s3-bucket")

  object_lock_enabled = var.object_lock_configuration != null
  logging_enabled     = var.logging_target_bucket != null && var.logging_target_bucket != ""
  replication_enabled = length(var.replication_rules) > 0
  inventory_enabled   = length(var.inventory_configurations) > 0

  kms_enabled = var.kms_key_arn != null || var.create_kms_key
  kms_key_id = (
    var.kms_key_arn != null
    ? var.kms_key_arn
    : (var.create_kms_key ? one(aws_kms_key.s3[*].arn) : null)
  )
  sse_algorithm = local.kms_enabled ? "aws:kms" : "AES256"

  versioning_status = (
    var.versioning_enabled || local.object_lock_enabled || local.replication_enabled
    ? "Enabled"
    : "Suspended"
  )

  common_tags = merge(var.tags, {
    ManagedBy = "terraform"
  })
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "name" {
  description = "Name of the S3 bucket. Mutually exclusive with name_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.name == null ? true : length(var.name) <= 63
    error_message = "The bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate the S3 bucket name. Mutually exclusive with name."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null ? true : length(var.name_prefix) <= 37
    error_message = "The bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Whether all objects must be deleted so the bucket can be destroyed."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition = contains(
      ["BucketOwnerEnforced", "ObjectWriter", "BucketOwnerPreferred"],
      var.object_ownership,
    )
    error_message = "object_ownership must be one of BucketOwnerEnforced, ObjectWriter, or BucketOwnerPreferred."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies for the bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies for the bucket."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of a customer managed KMS key used for SSE-KMS."
  type        = string
  default     = null
}

variable "create_kms_key" {
  description = "Create a customer managed KMS key in this configuration and use it for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_enabled" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "eventbridge_enabled" {
  description = "Enable EventBridge notifications for the bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of the bucket that receives server access logs. Declared in this configuration."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix applied to delivered server access logs."
  type        = string
  default     = "logs/"
}

variable "logging_source_bucket_arns" {
  description = "ARNs of buckets allowed to deliver server access logs into this bucket."
  type        = list(string)
  default     = []
}

variable "object_lock_configuration" {
  description = "Object Lock configuration (mode plus days or years)."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_rules" {
  description = "Cross-region replication rules for the bucket."
  type = list(object({
    id                 = string
    priority           = optional(number)
    status             = optional(string, "Enabled")
    filter_prefix      = optional(string)
    storage_class      = optional(string)
    replica_kms_key_id = optional(string)
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(bool, false)
    }))
  }))
  default = []
}

variable "inventory_configurations" {
  description = "S3 Inventory configurations for the bucket."
  type = list(object({
    name                     = string
    included_object_versions = optional(string, "All")
    schedule_frequency       = optional(string, "Weekly")
    output_format            = optional(string, "Parquet")
    prefix                   = optional(string)
    encryption_sse           = optional(string, "SSE-S3")
    kms_key_arn              = optional(string)
  }))
  default = []
}

variable "cors_rules" {
  description = "CORS rules for the bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Lifecycle rules for the bucket."
  type = list(object({
    id            = string
    status        = optional(string, "Enabled")
    filter_prefix = optional(string)
    expiration = optional(object({
      days = number
    }))
    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })), [])
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "custom_bucket_policy" {
  description = "Optional JSON policy document merged into the bucket policy."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# KMS key (optional, created in-line when KMS encryption is required)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  count = var.create_kms_key && var.kms_key_arn == null ? 1 : 0

  description             = "KMS key used to encrypt S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.bucket_name}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Primary bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.use_name ? var.name : null
  bucket_prefix = local.use_name ? null : local.bucket_name
  force_destroy = var.force_destroy

  object_lock_enabled = local.object_lock_enabled

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = !(local.use_name && var.name_prefix != null && var.name_prefix != "")
      error_message = "Only one of \"name\" or \"name_prefix\" may be specified."
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "main" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.kms_enabled ? local.kms_key_id : null
    }

    bucket_key_enabled = local.kms_enabled
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = local.versioning_status
  }
}

# -----------------------------------------------------------------------------
# Bucket policy: custom statements + mandatory SSL deny + conditional logging allow
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "bucket" {
  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "AllowS3ServerAccessLogging"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.main.arn}/*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.main]
}

# -----------------------------------------------------------------------------
# EventBridge notifications
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_notification" "main" {
  count = var.eventbridge_enabled ? 1 : 0

  bucket      = aws_s3_bucket.main.id
  eventbridge = true
}

# -----------------------------------------------------------------------------
# Server access logging (target bucket declared here)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "logging_target" {
  count = local.logging_enabled ? 1 : 0

  bucket        = var.logging_target_bucket
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = var.logging_target_bucket
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging_target" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging_target[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging_target" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging_target[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "logging_target" {
  count = local.logging_enabled ? 1 : 0

  statement {
    sid    = "AllowS3ServerAccessLogging"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logging_target[0].arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "logging_target" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging_target[0].id
  policy = data.aws_iam_policy_document.logging_target[0].json

  depends_on = [aws_s3_bucket_public_access_block.logging_target]
}

resource "aws_s3_bucket_logging" "main" {
  count = local.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging_target[0].id
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = !local.object_lock_enabled
      error_message = "Server access logging cannot be enabled on a bucket that also has Object Lock enabled."
    }
  }
}

# -----------------------------------------------------------------------------
# Object Lock
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = local.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]

  lifecycle {
    precondition {
      condition     = !local.logging_enabled
      error_message = "Object Lock cannot be enabled on a bucket that is also used as a server access logging source."
    }
  }
}

# -----------------------------------------------------------------------------
# Cross-region replication
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "replication_destination" {
  count = local.replication_enabled ? 1 : 0

  bucket_prefix = "replica-"
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = "replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_destination" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.replication_enabled ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.replication_enabled ? 1 : 0

  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = merge(local.common_tags, {
    Name = "s3-replication"
  })
}

data "aws_iam_policy_document" "replication" {
  count = local.replication_enabled ? 1 : 0

  statement {
    sid    = "SourceBucketReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationBucketWritePermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.replication_destination[0].arn}/*"]
  }

  dynamic "statement" {
    for_each = local.kms_enabled ? [1] : []

    content {
      sid    = "KmsPermissions"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKey",
      ]

      resources = [local.kms_key_id]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count = local.replication_enabled ? 1 : 0

  name_prefix = "s3-replication-"
  policy      = data.aws_iam_policy_document.replication[0].json

  tags = merge(local.common_tags, {
    Name = "s3-replication"
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.replication_enabled ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "main" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter_prefix != null ? [rule.value.filter_prefix] : []

        content {
          prefix = filter.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []

        content {
          sse_kms_encrypted_objects {
            status = source_selection_criteria.value.sse_kms_encrypted_objects ? "Enabled" : "Disabled"
          }
        }
      }

      destination {
        bucket        = aws_s3_bucket.replication_destination[0].arn
        storage_class = rule.value.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_id != null ? [rule.value.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.main,
    aws_s3_bucket_versioning.replication_destination,
    aws_iam_role_policy_attachment.replication,
  ]
}

# -----------------------------------------------------------------------------
# S3 Inventory
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  bucket_prefix = "inventory-"
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = "inventory"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  bucket = aws_s3_bucket.inventory_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  bucket = aws_s3_bucket.inventory_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  statement {
    sid    = "AllowS3InventoryDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.inventory_destination[0].arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  bucket = aws_s3_bucket.inventory_destination[0].id
  policy = data.aws_iam_policy_document.inventory_destination[0].json

  depends_on = [aws_s3_bucket_public_access_block.inventory_destination]
}

resource "aws_s3_bucket_inventory" "main" {
  for_each = { for cfg in var.inventory_configurations : cfg.name => cfg }

  bucket                   = aws_s3_bucket.main.id
  name                     = each.value.name
  included_object_versions = each.value.included_object_versions
  enabled                  = true

  schedule {
    frequency = each.value.schedule_frequency
  }

  dynamic "filter" {
    for_each = each.value.prefix != null ? [each.value.prefix] : []

    content {
      prefix = filter.value
    }
  }

  destination {
    bucket {
      format     = each.value.output_format
      bucket_arn = aws_s3_bucket.inventory_destination[0].arn
      prefix     = each.value.prefix

      dynamic "encryption" {
        for_each = each.value.encryption_sse != null ? [each.value.encryption_sse] : []

        content {
          dynamic "sse_kms" {
            for_each = encryption.value == "SSE-KMS" ? [1] : []

            content {
              key_id = each.value.kms_key_arn != null ? each.value.kms_key_arn : local.kms_key_id
            }
          }

          dynamic "sse_s3" {
            for_each = encryption.value == "SSE-S3" ? [1] : []

            content {}
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.inventory_destination]
}

# -----------------------------------------------------------------------------
# CORS
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter_prefix != null ? [rule.value.filter_prefix] : []

        content {
          prefix = filter.value
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days = expiration.value.days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "group_name_prefix" {
  type        = string
  default     = "app"
  description = "Prefix applied to the developer and admin IAM group names."
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  common_tags = {
    Environment = "security-baseline"
    ManagedBy   = "terraform"
    Owner       = "security-team"
  }
}

# -----------------------------------------------------------------------------
# Account-wide security baselines
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "main" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
}

resource "aws_s3_account_public_access_block" "main" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# IAM groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# -----------------------------------------------------------------------------
# Developer group: AWS-managed policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developer_managed_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_managed_iam_user_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_managed_iam_user_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# -----------------------------------------------------------------------------
# Developer custom policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "developer_self_service_keys" {
  name        = "${var.group_name_prefix}_developer_self_service_keys"
  description = "Allow developers to manage only their own IAM access keys."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:ListAccessKeys",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey"
        ]
        Resource = "arn:aws:iam::${local.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_policy" "developer_virtual_mfa" {
  name        = "${var.group_name_prefix}_developer_virtual_mfa"
  description = "Allow developers to self-manage their own virtual MFA device, requiring MFA to deactivate it."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${local.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${local.account_id}:user/$${aws:username}"
        ]
      },
      {
        Sid    = "RequireMFAToDeactivateVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${local.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${local.account_id}:user/$${aws:username}"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "developer_s3_mfa" {
  name        = "${var.group_name_prefix}_developer_s3_mfa"
  description = "MFA-gated S3 access, region-locked bucket creation, and protection of the Terraform state bucket."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3WithMFA"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:GetBucketPolicy",
          "s3:PutBucketPolicy"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid       = "DenyBucketCreationOutsideHomeRegion"
        Effect    = "Deny"
        Action    = ["s3:CreateBucket"]
        Resource  = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = local.region
          }
        }
      },
      {
        Sid    = "DenyAccessToTerraformStateBucket"
        Effect = "Deny"
        Action = ["s3:*"]
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "developer_mfa_services" {
  name        = "${var.group_name_prefix}_developer_mfa_services"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling, and the related service-linked roles."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2WithMFA"
        Effect   = "Allow"
        Action   = ["ec2:*"]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "ElasticLoadBalancingWithMFA"
        Effect   = "Allow"
        Action   = ["elasticloadbalancing:*"]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "CloudWatchWithMFA"
        Effect   = "Allow"
        Action   = ["cloudwatch:*", "logs:*"]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "AutoScalingWithMFA"
        Effect   = "Allow"
        Action   = ["autoscaling:*"]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "PassServiceLinkedRolesWithMFA"
        Effect   = "Allow"
        Action   = ["iam:PassRole"]
        Resource = [
          "arn:aws:iam::${local.account_id}:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2Spot",
          "arn:aws:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Developer group: custom policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developer_custom_self_service_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_service_keys.arn
}

resource "aws_iam_group_policy_attachment" "developer_custom_virtual_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_virtual_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developer_custom_s3_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developer_custom_mfa_services" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_services.arn
}

# -----------------------------------------------------------------------------
# Customer managed KMS key for the remote-state bucket (SSE-KMS)
# -----------------------------------------------------------------------------

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed key for encrypting the Terraform remote-state bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/${var.group_name_prefix}-terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# -----------------------------------------------------------------------------
# Designated remote-state bucket (referenced by the developer deny statement)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "terraform_state" {
  bucket = "${var.group_name_prefix}-terraform-state-${local.account_id}"
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Administrative role and policies
# -----------------------------------------------------------------------------

resource "aws_iam_role" "admin" {
  name        = "admin"
  description = "Administrative role assumable only by the account root principal and only with MFA."
  tags        = local.common_tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountRootToAssumeRole"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "admin_full_access" {
  name        = "${var.group_name_prefix}_admin_full_access"
  description = "Deliberate full administrative access, strictly conditioned on MFA being present."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccessWithMFA"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = "${var.group_name_prefix}_admin_assume_role"
  description = "Allow admin group members to assume the admin role only when MFA is present."
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AssumeAdminRoleWithMFA"
        Effect   = "Allow"
        Action   = ["sts:AssumeRole"]
        Resource = [aws_iam_role.admin.arn]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "config" {
  description = "Path to the YAML document that drives the orchestration framework."
  type        = string
  default     = "config/pipelines.yaml"
}

variable "name_prefix" {
  description = "Prefix applied to the framework's globally unique resource names."
  type        = string
  default     = "terraforest"
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

variable "create_default_pipeline_role" {
  description = "Create the shared default CodePipeline service role under /terraforest/."
  type        = bool
  default     = true
}

###############################################################################
# Provider metadata (static / local lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

###############################################################################
# Configuration parsing
###############################################################################

locals {
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id

  tags = merge(
    {
      ManagedBy = "Terraform"
      Project   = var.name_prefix
      Framework = "terraforest"
    },
    var.tags,
  )

  # ---------------------------------------------------------------------------
  # YAML document. Every lookup is wrapped in try()/lookup() so that missing
  # optional sections are tolerated and unknown keys are ignored.
  # ---------------------------------------------------------------------------
  config_source = try(file(var.config), "")
  config        = local.config_source == "" ? {} : try(yamldecode(local.config_source), {})
  settings      = try(local.config, {})

  settings_map         = try(local.config.settings, {})
  cache_retention_days = try(local.settings_map.cache_retention_days, 30)
  log_retention_days   = try(local.settings_map.log_retention_days, 30)
  source_prefix        = try(local.settings_map.source_prefix, "sources")
  vpc_cidr             = try(local.settings_map.vpc_cidr_block, "10.42.0.0/16")

  pipelines   = try(local.config.pipelines, {})
  connections = try(local.config.connections, {})
  event_rules = try(local.config.event_rules, {})
  secret_defs = try(local.config.secrets, {})

  default_action_category = {
    CodeCommit               = "Source"
    S3                       = "Source"
    ECR                      = "Source"
    CodeStarSourceConnection = "Source"
    CodeBuild                = "Build"
    Lambda                   = "Invoke"
    Manual                   = "Approval"
  }

  supported_lambda_runtimes = [
    "python3.12",
    "python3.11",
    "python3.10",
    "python3.9",
    "python3.8",
    "nodejs20.x",
    "nodejs18.x",
    "java21",
    "java17",
    "java11",
    "dotnet8",
    "dotnet6",
    "go1.x",
    "ruby3.2",
  ]

  # ---------------------------------------------------------------------------
  # Source repositories are derived from the source actions declared in the
  # pipelines and can be extended/overridden by dedicated top level sections.
  # ---------------------------------------------------------------------------
  codecommit_repositories = merge(
    {
      for action in flatten([
        for _, pipeline in local.pipelines : [
          for stage in try(pipeline.stages, []) : [
            for a in try(stage.actions, []) : a
            if try(a.provider, "") == "CodeCommit" && try(a.repository, null) != null
          ]
        ]
      ]) : action.repository => {
        default_branch = try(action.branch, "main")
        description    = try(action.description, "Managed by terraforest")
      }
    },
    try(local.config.codecommit_repositories, {}),
  )

  ecr_repositories = merge(
    {
      for action in flatten([
        for _, pipeline in local.pipelines : [
          for stage in try(pipeline.stages, []) : [
            for a in try(stage.actions, []) : a
            if try(a.provider, "") == "ECR" && try(a.repository, null) != null
          ]
        ]
      ]) : action.repository => {
        image_tag_mutability = try(action.image_tag_mutability, "MUTABLE")
        description          = try(action.description, "Managed by terraforest")
      }
    },
    try(local.config.ecr_repositories, {}),
  )

  # ---------------------------------------------------------------------------
  # Build / invoke actions: declared either in dedicated top level sections or
  # inlined inside pipeline actions.
  # ---------------------------------------------------------------------------
  codebuild_actions = merge(
    {
      for spec in flatten([
        for _, pipeline in local.pipelines : [
          for stage in try(pipeline.stages, []) : [
            for a in try(stage.actions, []) : {
              key  = try(a.project, try(a.name, "build"))
              spec = try(a.build, {})
            }
            if try(a.build, null) != null
          ]
        ]
      ]) : spec.key => spec.spec
    },
    try(local.config.codebuild_actions, {}),
  )

  lambda_actions = merge(
    {
      for spec in flatten([
        for _, pipeline in local.pipelines : [
          for stage in try(pipeline.stages, []) : [
            for a in try(stage.actions, []) : {
              key  = try(a.function, try(a.name, "function"))
              spec = try(a.lambda, {})
            }
            if try(a.lambda, null) != null
          ]
        ]
      ]) : spec.key => spec.spec
    },
    try(local.config.lambda_actions, {}),
  )

  # ---------------------------------------------------------------------------
  # Fully resolved CodePipeline stage/action model.
  # ---------------------------------------------------------------------------
  pipeline_stages = {
    for pkey, pipeline in local.pipelines : pkey => [
      for s_idx, stage in try(pipeline.stages, []) : {
        name = try(stage.name, "Stage${s_idx + 1}")
        actions = [
          for a_idx, action in try(stage.actions, []) : {
            name             = try(action.name, "Action${a_idx + 1}")
            category         = try(action.category, try(local.default_action_category[try(action.provider, "")], "Build"))
            owner            = try(action.owner, "AWS")
            provider         = try(action.provider, "CodeBuild")
            version          = try(action.version, "1")
            run_order        = try(action.run_order, null)
            input_artifacts  = try(action.input_artifacts, [])
            output_artifacts = try(action.output_artifacts, [])
            role_arn         = try(action.role_arn, null)

            configuration = merge(
              try(action.configuration, {}),

              try(action.provider, "") == "CodeCommit" ? {
                RepositoryName       = try(aws_codecommit_repository.repositories[try(action.repository, try(action.name, ""))].repository_name, try(action.repository, try(action.name, "")))
                BranchName           = try(action.branch, "main")
                PollForSourceChanges = "false"
              } : {},

              try(action.provider, "") == "S3" ? {
                S3Bucket             = aws_s3_bucket.artifacts.id
                S3ObjectKey          = try(action.s3_object_key, "${local.source_prefix}/${try(action.name, "source")}.zip")
                PollForSourceChanges = "false"
              } : {},

              try(action.provider, "") == "ECR" ? {
                RepositoryName = try(aws_ecr_repository.repositories[try(action.repository, try(action.name, ""))].name, try(action.repository, try(action.name, "")))
                ImageTag       = try(action.image_tag, "latest")
              } : {},

              try(action.provider, "") == "CodeStarSourceConnection" ? {
                ConnectionArn        = try(aws_codestarconnections_connection.connections[try(action.connection, try(action.name, ""))].arn, try(action.connection_arn, ""))
                FullRepositoryId     = try(action.full_repository_id, "")
                BranchName           = try(action.branch, "main")
                OutputArtifactFormat = try(action.output_artifact_format, "CODEBUILD_CLONE_REF")
                PollForSourceChanges = "false"
              } : {},

              try(action.provider, "") == "CodeBuild" ? {
                ProjectName = try(aws_codebuild_project.builds[try(action.project, try(action.name, ""))].name, try(action.project, try(action.name, "")))
              } : {},

              try(action.provider, "") == "Lambda" ? {
                FunctionName   = try(aws_lambda_function.functions[try(action.function, try(action.name, ""))].function_name, try(action.function, try(action.name, "")))
                UserParameters = jsonencode(try(action.user_parameters, {}))
              } : {},

              try(action.category, "") == "Approval" || try(action.provider, "") == "Manual" ? merge(
                { CustomData = try(action.custom_data, "Approved") },
                try(action.notification_arn, null) != null ? { NotificationArn = action.notification_arn } : {},
                try(action.external_entity_link, null) != null ? { ExternalEntityLink = action.external_entity_link } : {},
              ) : {},
            )
          }
        ]
      }
    ]
  }

  # ---------------------------------------------------------------------------
  # EventBridge trigger model.
  # ---------------------------------------------------------------------------
  rule_is_schedule = { for k, v in local.event_rules : k => try(v.type, "") == "schedule" }

  rule_patterns = {
    for k, v in local.event_rules : k => (
      try(v.type, "") == "branch" || try(v.type, "") == "tag" ? merge(
        {
          source        = ["aws.codecommit"]
          "detail-type" = ["CodeCommit Repository State Change"]
          detail = merge(
            {
              event         = ["referenceCreated", "referenceUpdated"]
              referenceType = [try(v.type, "") == "tag" ? "tag" : "branch"]
              referenceName = try(v.type, "") == "tag" ? try(v.tags, ["*"]) : try(v.branches, ["*"])
            },
            try(v.repositories, null) != null ? { repositoryName = v.repositories } : {},
          )
        },
        try(v.pattern, {}),
      ) : try(v.pattern, {})
    )
  }

  # ---------------------------------------------------------------------------
  # Networking is provisioned only when a build or invoke action requests it.
  # A single boolean gates the VPC, subnets, and every dependent resource so
  # that the collections can never diverge (which would produce dangling
  # index references such as aws_vpc.framework["main"]).
  # ---------------------------------------------------------------------------
  vpc_enabled = length(concat(
    [for k, v in local.codebuild_actions : k if try(v.vpc, false)],
    [for k, v in local.lambda_actions : k if try(v.vpc, false)],
  )) > 0

  vpc_map = local.vpc_enabled ? { "main" = true } : {}

  az_names = slice(
    data.aws_availability_zones.available.names,
    0,
    min(3, length(data.aws_availability_zones.available.names)),
  )

  subnet_map = local.vpc_enabled ? { for idx, az in local.az_names : az => idx } : {}

  # ---------------------------------------------------------------------------
  # Resource ARN collections used to scope IAM policies.
  # ---------------------------------------------------------------------------
  codecommit_repository_arns = [for r in aws_codecommit_repository.repositories : r.arn]
  codebuild_project_arns     = [for p in aws_codebuild_project.builds : p.arn]
  ecr_repository_arns        = [for r in aws_ecr_repository.repositories : r.arn]
  connection_arn_list        = [for c in aws_codestarconnections_connection.connections : c.arn]
  lambda_function_arns       = [for f in aws_lambda_function.functions : f.arn]
}

###############################################################################
# Encryption
###############################################################################

resource "aws_kms_key" "artifacts" {
  description             = "${var.name_prefix} CI/CD artifact encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.tags, { Name = "${var.name_prefix}-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "artifacts" {
  name          = "alias/${lower(var.name_prefix)}-artifacts"
  target_key_id = aws_kms_key.artifacts.key_id
}

resource "aws_kms_key_policy" "artifacts" {
  key_id = aws_kms_key.artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "KeyAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = aws_kms_key.artifacts.arn
      },
      {
        Sid       = "AllowCloudWatchLogsEncryption"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*",
        ]
        Resource = aws_kms_key.artifacts.arn
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
          }
        }
      },
    ]
  })
}

###############################################################################
# Artifact bucket
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket        = lower("${var.name_prefix}-artifacts-${local.account_id}-${local.region}")
  force_destroy = false

  tags = merge(local.tags, { Name = "${var.name_prefix}-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifacts.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Build cache bucket
###############################################################################

resource "aws_s3_bucket" "build_cache" {
  bucket        = lower("${var.name_prefix}-build-cache-${local.account_id}-${local.region}")
  force_destroy = false

  tags = merge(local.tags, { Name = "${var.name_prefix}-build-cache" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifacts.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    id     = "expire-build-cache"
    status = "Enabled"

    filter {
      prefix = "cache/"
    }

    expiration {
      days = local.cache_retention_days
    }

    noncurrent_version_expiration {
      noncurrent_days = local.cache_retention_days
    }
  }

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

###############################################################################
# Source repositories
###############################################################################

resource "aws_codecommit_repository" "repositories" {
  for_each = local.codecommit_repositories

  repository_name = each.key
  default_branch  = try(each.value.default_branch, "main")
  description     = try(each.value.description, "Managed by terraforest")

  tags = merge(local.tags, { ManagedBy = "Terraform" })
}

resource "aws_ecr_repository" "repositories" {
  for_each = local.ecr_repositories

  name                 = each.key
  image_tag_mutability = try(each.value.image_tag_mutability, "MUTABLE")

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.artifacts.arn
  }

  tags = merge(local.tags, { ManagedBy = "Terraform" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codestarconnections_connection" "connections" {
  for_each = local.connections

  name          = each.key
  provider_type = try(each.value.provider_type, "GitHub")

  tags = merge(local.tags, { ManagedBy = "Terraform" })
}

###############################################################################
# Default CodePipeline service role (/terraforest/)
###############################################################################

resource "aws_iam_role" "codepipeline" {
  for_each = var.create_default_pipeline_role ? { "default" = true } : {}

  name = "${var.name_prefix}-codepipeline"
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "CodePipelineAssumeRole"
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "codepipeline.amazonaws.com" }
    }]
  })

  tags = merge(local.tags, { Name = "${var.name_prefix}-codepipeline" })
}

resource "aws_iam_role_policy" "codepipeline" {
  for_each = var.create_default_pipeline_role ? { "default" = true } : {}

  name = "${var.name_prefix}-codepipeline"
  role = aws_iam_role.codepipeline[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitSourceAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GetRepository",
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GitPull",
        ]
        Resource = length(local.codecommit_repository_arns) > 0 ? local.codecommit_repository_arns : ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:*"]
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:BatchGetProjects",
        ]
        Resource = length(local.codebuild_project_arns) > 0 ? local.codebuild_project_arns : ["arn:${local.partition}:codebuild:${local.region}:${local.account_id}:project/*"]
      },
      {
        Sid      = "EcrAuthorization"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = ["*"]
      },
      {
        Sid    = "EcrImageAccess"
        Effect = "Allow"
        Action = [
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
        ]
        Resource = length(local.ecr_repository_arns) > 0 ? local.ecr_repository_arns : ["arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"]
      },
      {
        Sid      = "CodeStarConnectionsAccess"
        Effect   = "Allow"
        Action   = ["codestar-connections:UseConnection"]
        Resource = length(local.connection_arn_list) > 0 ? local.connection_arn_list : ["arn:${local.partition}:codestar-connections:${local.region}:${local.account_id}:connection/*"]
      },
      {
        Sid    = "ArtifactBucketObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
        ]
        Resource = [
          "${aws_s3_bucket.artifacts.arn}/*",
          "${aws_s3_bucket.build_cache.arn}/*",
        ]
      },
      {
        Sid    = "ArtifactBucketListAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetBucketVersioning",
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          aws_s3_bucket.build_cache.arn,
        ]
      },
      {
        Sid      = "LambdaInvokeAccess"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = length(local.lambda_function_arns) > 0 ? local.lambda_function_arns : ["arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"]
      },
      {
        Sid    = "ArtifactKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = [aws_kms_key.artifacts.arn]
      },
    ]
  })
}

###############################################################################
# CodeBuild projects
###############################################################################

resource "aws_cloudwatch_log_group" "codebuild" {
  for_each = local.codebuild_actions

  name              = "/aws/codebuild/${each.key}"
  retention_in_days = local.log_retention_days
  kms_key_id        = aws_kms_key.artifacts.arn

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-logs" })
}

resource "aws_iam_role" "codebuild" {
  for_each = local.codebuild_actions

  name = "${var.name_prefix}-codebuild-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "CodeBuildAssumeRole"
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "codebuild.amazonaws.com" }
    }]
  })

  tags = merge(local.tags, { Name = "${var.name_prefix}-codebuild-${each.key}" })
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = local.codebuild_actions

  name = "${var.name_prefix}-codebuild-${each.key}"
  role = aws_iam_role.codebuild[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "CloudWatchLogs"
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
          ]
          Resource = [
            aws_cloudwatch_log_group.codebuild[each.key].arn,
            "${aws_cloudwatch_log_group.codebuild[each.key].arn}:*",
          ]
        },
        {
          Sid    = "ArtifactBucketAccess"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:PutObject",
            "s3:ListBucket",
            "s3:GetBucketLocation",
            "s3:GetBucketVersioning",
          ]
          Resource = [
            aws_s3_bucket.artifacts.arn,
            "${aws_s3_bucket.artifacts.arn}/*",
          ]
        },
        {
          Sid    = "CacheBucketAccess"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:PutObject",
            "s3:DeleteObject",
            "s3:ListBucket",
            "s3:GetBucketLocation",
          ]
          Resource = [
            aws_s3_bucket.build_cache.arn,
            "${aws_s3_bucket.build_cache.arn}/*",
          ]
        },
        {
          Sid      = "EcrAuthorization"
          Effect   = "Allow"
          Action   = ["ecr:GetAuthorizationToken"]
          Resource = ["*"]
        },
        {
          Sid    = "EcrRepositoryAccess"
          Effect = "Allow"
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:BatchGetImage",
            "ecr:GetDownloadUrlForLayer",
            "ecr:InitiateLayerUpload",
            "ecr:UploadLayerPart",
            "ecr:CompleteLayerUpload",
            "ecr:PutImage",
          ]
          Resource = length(local.ecr_repository_arns) > 0 ? local.ecr_repository_arns : ["arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"]
        },
        {
          Sid    = "ArtifactKeyUsage"
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:Encrypt",
            "kms:GenerateDataKey",
            "kms:DescribeKey",
          ]
          Resource = [aws_kms_key.artifacts.arn]
        },
      ],
      try(each.value.vpc, false) ? [
        {
          Sid    = "VpcNetworking"
          Effect = "Allow"
          Action = [
            "ec2:CreateNetworkInterface",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs",
          ]
          Resource = ["*"]
        },
      ] : [],
    )
  })
}

resource "aws_codebuild_project" "builds" {
  for_each = local.codebuild_actions

  name           = each.key
  description    = try(each.value.description, "terraforest managed build project ${each.key}")
  service_role   = aws_iam_role.codebuild[each.key].arn
  build_timeout  = try(each.value.build_timeout, 60)
  encryption_key = aws_kms_key.artifacts.arn

  tags = merge(local.tags, { Pipeline = try(each.value.pipeline, var.name_prefix) })

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type     = "S3"
    location = "${aws_s3_bucket.build_cache.id}/${try(each.value.cache_prefix, "cache")}"
  }

  environment {
    compute_type                = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
    image                       = try(each.value.image, "aws/codebuild/amazonlinux2-x86_64-standard:5.0")
    type                        = try(each.value.environment_type, "LINUX_CONTAINER")
    image_pull_credentials_type = try(each.value.image_pull_credentials_type, "CODEBUILD")
    privileged_mode             = try(each.value.privileged_mode, false)

    dynamic "environment_variable" {
      for_each = try(each.value.environment_variables, {})

      content {
        name  = environment_variable.key
        value = environment_variable.value
        type  = "PLAINTEXT"
      }
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild[each.key].name
      stream_name = try(each.value.log_stream_name, "build")
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = try(each.value.buildspec, null)
  }

  dynamic "vpc_config" {
    for_each = try(each.value.vpc, false) ? [1] : []

    content {
      vpc_id             = aws_vpc.framework["main"].id
      subnets            = [for s in aws_subnet.private_subnets : s.id]
      security_group_ids = [aws_security_group.workloads["main"].id]
    }
  }
}

###############################################################################
# Lambda invoke actions
###############################################################################

resource "aws_cloudwatch_log_group" "lambda" {
  for_each = local.lambda_actions

  name              = "/aws/lambda/${var.name_prefix}-${each.key}"
  retention_in_days = local.log_retention_days
  kms_key_id        = aws_kms_key.artifacts.arn

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-logs" })
}

resource "aws_iam_role" "lambda" {
  for_each = local.lambda_actions

  name = "${var.name_prefix}-lambda-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "LambdaAssumeRole"
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "lambda.amazonaws.com" }
    }]
  })

  tags = merge(local.tags, { Name = "${var.name_prefix}-lambda-${each.key}" })
}

resource "aws_iam_role_policy" "lambda" {
  for_each = local.lambda_actions

  name = "${var.name_prefix}-lambda-${each.key}"
  role = aws_iam_role.lambda[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "CloudWatchLogs"
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
          ]
          Resource = [
            aws_cloudwatch_log_group.lambda[each.key].arn,
            "${aws_cloudwatch_log_group.lambda[each.key].arn}:*",
          ]
        },
        {
          Sid    = "ArtifactBucketReadAccess"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:ListBucket",
            "s3:GetBucketLocation",
          ]
          Resource = [
            aws_s3_bucket.artifacts.arn,
            "${aws_s3_bucket.artifacts.arn}/*",
          ]
        },
        {
          Sid    = "ArtifactKeyUsage"
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:Encrypt",
            "kms:GenerateDataKey",
            "kms:DescribeKey",
          ]
          Resource = [aws_kms_key.artifacts.arn]
        },
      ],
      try(each.value.vpc, false) ? [
        {
          Sid    = "VpcNetworking"
          Effect = "Allow"
          Action = [
            "ec2:CreateNetworkInterface",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
          ]
          Resource = ["*"]
        },
      ] : [],
    )
  })
}

resource "aws_lambda_function" "functions" {
  for_each = local.lambda_actions

  function_name = "${var.name_prefix}-${each.key}"
  role          = aws_iam_role.lambda[each.key].arn
  handler       = try(each.value.handler, "index.handler")
  memory_size   = try(each.value.memory_size, 128)
  timeout       = try(each.value.timeout, 30)

  runtime = contains(local.supported_lambda_runtimes, try(each.value.runtime, "python3.12")) ? try(each.value.runtime, "python3.12") : "python3.12"

  # Deployment packages are supplied either through S3 or as a local archive.
  # No secret material is ever placed in environment variables.
  filename          = try(each.value.s3_bucket, null) == null ? try(each.value.filename, "${path.module}/packages/${each.key}.zip") : null
  s3_bucket         = try(each.value.s3_bucket, null)
  s3_key            = try(each.value.s3_key, null)
  s3_object_version = try(each.value.s3_object_version, null)
  source_code_hash  = try(each.value.s3_bucket, null) == null ? filebase64sha256(try(each.value.filename, "${path.module}/packages/${each.key}.zip")) : null

  environment {
    variables = try(each.value.environment, {})
  }

  dynamic "vpc_config" {
    for_each = try(each.value.vpc, false) ? [1] : []

    content {
      subnet_ids         = [for s in aws_subnet.private_subnets : s.id]
      security_group_ids = [aws_security_group.workloads["main"].id]
    }
  }

  tags = merge(local.tags, { Pipeline = try(each.value.pipeline, var.name_prefix) })

  depends_on = [aws_cloudwatch_log_group.lambda]
}

resource "aws_lambda_permission" "codepipeline" {
  for_each = local.lambda_actions

  statement_id  = "AllowExecutionFromCodePipeline"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.functions[each.key].function_name
  principal     = "codepipeline.amazonaws.com"
}

###############################################################################
# CodePipeline pipelines
###############################################################################

resource "aws_codepipeline" "pipelines" {
  for_each = local.pipelines

  name          = each.key
  pipeline_type = try(each.value.pipeline_type, "V1")
  role_arn      = coalesce(try(each.value.role_arn, null), one(aws_iam_role.codepipeline[*].arn))

  tags = merge(local.tags, { Pipeline = each.key, Name = each.key })

  artifact_store {
    location = aws_s3_bucket.artifacts.id
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.artifacts.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = local.pipeline_stages[each.key]

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = action.value.run_order
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          role_arn         = action.value.role_arn

          configuration = { for k, v in action.value.configuration : k => tostring(v) }
        }
      }
    }
  }
}

resource "aws_codepipeline_webhook" "webhooks" {
  for_each = { for k, p in local.pipelines : k => p if try(p.webhook.enabled, false) }

  name            = "${var.name_prefix}-${each.key}-webhook"
  authentication  = try(each.value.webhook.authentication, "UNAUTHENTICATED")
  target_action   = try(each.value.webhook.target_action, "Source")
  target_pipeline = aws_codepipeline.pipelines[each.key].name

  dynamic "filter" {
    for_each = try(each.value.webhook.filters, [])

    content {
      json_path    = filter.value.json_path
      match_equals = filter.value.match_equals
    }
  }

  tags = merge(local.tags, { Pipeline = each.key })
}

###############################################################################
# EventBridge triggers
###############################################################################

resource "aws_iam_role" "eventbridge" {
  for_each = local.pipelines

  name = "terrabits-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "EventBridgeAssumeRole"
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "events.amazonaws.com" }
    }]
  })

  tags = merge(local.tags, { Pipeline = each.key, Name = "terrabits-${each.key}" })
}

resource "aws_iam_role_policy" "eventbridge" {
  for_each = local.pipelines

  name = "terrabits-${each.key}-start-pipeline-execution"
  role = aws_iam_role.eventbridge[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid      = "StartPipelineExecution"
      Effect   = "Allow"
      Action   = ["codepipeline:StartPipelineExecution"]
      Resource = [aws_codepipeline.pipelines[each.key].arn]
    }]
  })
}

resource "aws_cloudwatch_event_rule" "rules" {
  for_each = local.event_rules

  name        = "terrabits-${each.key}"
  description = try(each.value.description, "terraforest trigger ${each.key}")

  schedule_expression = local.rule_is_schedule[each.key] ? try(each.value.schedule, try(each.value.schedule_expression, null)) : null
  event_pattern       = local.rule_is_schedule[each.key] ? null : jsonencode(local.rule_patterns[each.key])

  tags = merge(local.tags, { Pipeline = try(each.value.pipeline, each.key), Name = "terrabits-${each.key}" })
}

resource "aws_cloudwatch_event_target" "targets" {
  for_each = local.event_rules

  rule      = aws_cloudwatch_event_rule.rules[each.key].name
  target_id = try(each.value.target_id, replace(each.key, "/[^0-9A-Za-z_.-]/", "-"))
  arn       = aws_codepipeline.pipelines[try(each.value.pipeline, each.key)].arn
  role_arn  = aws_iam_role.eventbridge[try(each.value.pipeline, each.key)].arn

  dynamic "input_transformer" {
    for_each = try(each.value.input_transformer, null) != null ? [each.value.input_transformer] : []

    content {
      input_paths    = try(input_transformer.value.input_paths, {})
      input_template = input_transformer.value.input_template
    }
  }
}

###############################################################################
# Framework credentials (values are populated out of band)
###############################################################################

resource "aws_secretsmanager_secret" "credentials" {
  for_each = local.secret_defs

  name        = "${var.name_prefix}/${each.key}"
  description = try(each.value.description, "terraforest managed credential")
  kms_key_id  = aws_kms_key.artifacts.arn

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "credentials" {
  for_each = local.secret_defs

  secret_id     = aws_secretsmanager_secret.credentials[each.key].id
  secret_string = jsonencode({ managed_by = "terraforest", status = "populate-out-of-band" })

  lifecycle {
    ignore_changes = [secret_string]
  }
}

###############################################################################
# Optional networking (only when a build/invoke action requires a VPC)
###############################################################################

resource "aws_vpc" "framework" {
  for_each = local.vpc_map

  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${var.name_prefix}-vpc" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "framework" {
  for_each = local.vpc_map

  vpc_id = aws_vpc.framework[each.key].id

  tags = merge(local.tags, { Name = "${var.name_prefix}-igw" })
}

resource "aws_subnet" "public_subnets" {
  for_each = local.subnet_map

  vpc_id                  = aws_vpc.framework["main"].id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(local.vpc_cidr, 4, each.value)
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${var.name_prefix}-public-${each.key}" })
}

resource "aws_subnet" "private_subnets" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.framework["main"].id
  availability_zone = each.key
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, each.value + 8)

  tags = merge(local.tags, { Name = "${var.name_prefix}-private-${each.key}" })
}

resource "aws_eip" "nat" {
  for_each = local.vpc_map

  domain = "vpc"

  tags = merge(local.tags, { Name = "${var.name_prefix}-nat" })
}

resource "aws_nat_gateway" "framework" {
  for_each = local.vpc_map

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public_subnets[local.az_names[0]].id

  tags = merge(local.tags, { Name = "${var.name_prefix}-nat" })

  depends_on = [aws_internet_gateway.framework]
}

resource "aws_route_table" "public" {
  for_each = local.vpc_map

  vpc_id = aws_vpc.framework[each.key].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.framework[each.key].id
  }

  tags = merge(local.tags, { Name = "${var.name_prefix}-public" })
}

resource "aws_route_table" "private" {
  for_each = local.vpc_map

  vpc_id = aws_vpc.framework[each.key].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.framework[each.key].id
  }

  tags = merge(local.tags, { Name = "${var.name_prefix}-private" })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public_subnets

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public["main"].id
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private_subnets

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private["main"].id
}

resource "aws_security_group" "workloads" {
  for_each = local.vpc_map

  name        = "${var.name_prefix}-workloads"
  description = "Egress restricted security group for terraforest build and invoke workloads"
  vpc_id      = aws_vpc.framework[each.key].id

  tags = merge(local.tags, { Name = "${var.name_prefix}-workloads" })
}

resource "aws_vpc_security_group_egress_rule" "workloads_https" {
  for_each = local.vpc_map

  security_group_id = aws_security_group.workloads[each.key].id
  description       = "HTTPS egress for AWS service endpoints"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

###############################################################################
# Outputs
###############################################################################

output "pipeline_names" {
  description = "Map of pipeline keys to CodePipeline names."
  value       = { for k, p in aws_codepipeline.pipelines : k => p.name }
}

output "pipeline_arns" {
  description = "Map of pipeline keys to CodePipeline ARNs."
  value       = { for k, p in aws_codepipeline.pipelines : k => p.arn }
}

output "artifact_bucket_id" {
  description = "Name of the CodePipeline artifact bucket."
  value       = aws_s3_bucket.artifacts.id
}

output "artifact_bucket_arn" {
  description = "ARN of the CodePipeline artifact bucket."
  value       = aws_s3_bucket.artifacts.arn
}

output "build_cache_bucket_id" {
  description = "Name of the CodeBuild cache bucket."
  value       = aws_s3_bucket.build_cache.id
}

output "kms_key_arn" {
  description = "ARN of the framework customer managed KMS key."
  value       = aws_kms_key.artifacts.arn
}

output "connection_arns" {
  description = "Map of CodeStar connection keys to ARNs."
  value       = { for k, c in aws_codestarconnections_connection.connections : k => c.arn }
}

output "event_rule_names" {
  description = "Map of trigger keys to EventBridge rule names."
  value       = { for k, r in aws_cloudwatch_event_rule.rules : k => r.name }
}

output "eventbridge_role_arns" {
  description = "Map of pipeline keys to terrabits- prefixed EventBridge role ARNs."
  value       = { for k, r in aws_iam_role.eventbridge : k => r.arn }
}

output "codebuild_project_names" {
  description = "Map of build action keys to CodeBuild project names."
  value       = { for k, p in aws_codebuild_project.builds : k => p.name }
}

output "lambda_function_names" {
  description = "Map of invoke action keys to Lambda function names."
  value       = { for k, f in aws_lambda_function.functions : k => f.function_name }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables - module toggles
###############################################################################

variable "create" {
  description = "Master module toggle. When false, no security group, rule, or prefix list resources are created."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "When true a new security group is created. When false, rules are attached to var.existing_security_group_id."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of a caller-supplied existing security group. Empty by default so a greenfield account plans and applies unattended."
  type        = string
  default     = ""
}

variable "name" {
  description = "Base name used for the VPC, security group, prefix list and their Name tags."
  type        = string
  default     = "app-sg"
}

variable "security_group_description" {
  description = "Description applied to the newly created security group."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "vpc_cidr" {
  description = "CIDR block of the VPC created and owned by this module."
  type        = string
  default     = "10.0.0.0/16"
}

variable "revoke_rules_on_delete" {
  description = "Whether all rules attached to the security group are revoked before the group is deleted."
  type        = bool
  default     = true
}

variable "default_egress_cidr_ipv4" {
  description = "Optional IPv4 CIDR for an explicit default all-outbound egress rule on the new security group. Empty by default so the configuration emits no unrestricted egress rule (AWS still applies its default allow-all-outbound rule at runtime)."
  type        = string
  default     = ""

  validation {
    condition     = var.default_egress_cidr_ipv4 == "" || can(cidrhost(var.default_egress_cidr_ipv4, 0))
    error_message = "default_egress_cidr_ipv4 must be empty or a valid IPv4 CIDR block."
  }
}

variable "tags" {
  description = "Tags applied to every resource created by this module."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Variables - rule sets
###############################################################################

variable "new_ingress_rules" {
  description = "Ingress rules applied to the newly created security group. Exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id must be set per rule."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.new_ingress_rules :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] :
        s if s != null && s != ""
      ]) == 1
    ])
    error_message = "Each new_ingress_rules entry must specify exactly one source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.new_ingress_rules :
      !contains(["tcp", "udp", "6", "17"], lower(r.ip_protocol)) || (r.from_port != null && r.to_port != null)
    ])
    error_message = "new_ingress_rules entries with ip_protocol tcp/udp must set both from_port and to_port."
  }

  validation {
    condition = alltrue([
      for r in var.new_ingress_rules :
      (r.from_port == null || (r.from_port >= 0 && r.from_port <= 65535)) &&
      (r.to_port == null || (r.to_port >= 0 && r.to_port <= 65535)) &&
      (r.from_port == null || r.to_port == null || r.from_port <= r.to_port)
    ])
    error_message = "new_ingress_rules port values must be between 0 and 65535 with from_port <= to_port."
  }
}

variable "new_egress_rules" {
  description = "Egress rules applied to the newly created security group. When empty, no unrestricted egress rule is emitted by default."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.new_egress_rules :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] :
        s if s != null && s != ""
      ]) == 1
    ])
    error_message = "Each new_egress_rules entry must specify exactly one source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.new_egress_rules :
      !contains(["tcp", "udp", "6", "17"], lower(r.ip_protocol)) || (r.from_port != null && r.to_port != null)
    ])
    error_message = "new_egress_rules entries with ip_protocol tcp/udp must set both from_port and to_port."
  }

  validation {
    condition = alltrue([
      for r in var.new_egress_rules :
      (r.from_port == null || (r.from_port >= 0 && r.from_port <= 65535)) &&
      (r.to_port == null || (r.to_port >= 0 && r.to_port <= 65535)) &&
      (r.from_port == null || r.to_port == null || r.from_port <= r.to_port)
    ])
    error_message = "new_egress_rules port values must be between 0 and 65535 with from_port <= to_port."
  }
}

variable "existing_ingress_rules" {
  description = "Ingress rules applied to var.existing_security_group_id. Exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id must be set per rule."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_ingress_rules :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] :
        s if s != null && s != ""
      ]) == 1
    ])
    error_message = "Each existing_ingress_rules entry must specify exactly one source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.existing_ingress_rules :
      !contains(["tcp", "udp", "6", "17"], lower(r.ip_protocol)) || (r.from_port != null && r.to_port != null)
    ])
    error_message = "existing_ingress_rules entries with ip_protocol tcp/udp must set both from_port and to_port."
  }

  validation {
    condition = alltrue([
      for r in var.existing_ingress_rules :
      (r.from_port == null || (r.from_port >= 0 && r.from_port <= 65535)) &&
      (r.to_port == null || (r.to_port >= 0 && r.to_port <= 65535)) &&
      (r.from_port == null || r.to_port == null || r.from_port <= r.to_port)
    ])
    error_message = "existing_ingress_rules port values must be between 0 and 65535 with from_port <= to_port."
  }
}

variable "existing_egress_rules" {
  description = "Egress rules applied to var.existing_security_group_id. Exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id must be set per rule."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_egress_rules :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] :
        s if s != null && s != ""
      ]) == 1
    ])
    error_message = "Each existing_egress_rules entry must specify exactly one source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.existing_egress_rules :
      !contains(["tcp", "udp", "6", "17"], lower(r.ip_protocol)) || (r.from_port != null && r.to_port != null)
    ])
    error_message = "existing_egress_rules entries with ip_protocol tcp/udp must set both from_port and to_port."
  }

  validation {
    condition = alltrue([
      for r in var.existing_egress_rules :
      (r.from_port == null || (r.from_port >= 0 && r.from_port <= 65535)) &&
      (r.to_port == null || (r.to_port >= 0 && r.to_port <= 65535)) &&
      (r.from_port == null || r.to_port == null || r.from_port <= r.to_port)
    ])
    error_message = "existing_egress_rules port values must be between 0 and 65535 with from_port <= to_port."
  }
}

###############################################################################
# Variables - managed prefix list
###############################################################################

variable "create_prefix_list" {
  description = "When true, and no existing_prefix_list_ids are supplied, a customer-managed EC2 prefix list is created."
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list: IPv4 or IPv6."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the managed prefix list can hold."
  type        = number
  default     = 10

  validation {
    condition     = var.prefix_list_max_entries > 0
    error_message = "prefix_list_max_entries must be greater than zero."
  }
}

variable "prefix_list_entries" {
  description = "CIDR entries used to populate the customer-managed prefix list."
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_ids" {
  description = "Pre-existing managed prefix list IDs. When non-empty no prefix list is created and rules may reference these IDs."
  type        = list(string)
  default     = []
}

###############################################################################
# Locals
###############################################################################

locals {
  create_new_security_group = var.create && var.create_new_security_group
  create_existing_sg_rules  = var.create && !var.create_new_security_group && var.existing_security_group_id != ""
  create_prefix_list        = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0

  prefix_list_name = "${var.name}-prefix-list"

  # Optional, explicitly-opt-in default outbound rule. Emitting no unrestricted
  # egress rule by default keeps the configuration free of open egress; AWS still
  # applies its default allow-all-outbound rule to a newly created security group.
  default_egress_rules = var.default_egress_cidr_ipv4 != "" ? [{
    cidr_ipv4                    = var.default_egress_cidr_ipv4
    cidr_ipv6                    = null
    referenced_security_group_id = null
    prefix_list_id               = null
    ip_protocol                  = "-1"
    from_port                    = null
    to_port                      = null
    description                  = "Default outbound rule"
  }] : []

  effective_new_egress_rules = length(var.new_egress_rules) > 0 ? var.new_egress_rules : local.default_egress_rules

  new_ingress_rule_map = local.create_new_security_group ? {
    for i, r in var.new_ingress_rules : i => r
  } : {}

  new_egress_rule_map = local.create_new_security_group ? {
    for i, r in local.effective_new_egress_rules : i => r
  } : {}

  existing_ingress_rule_map = local.create_existing_sg_rules ? {
    for i, r in var.existing_ingress_rules : i => r
  } : {}

  existing_egress_rule_map = local.create_existing_sg_rules ? {
    for i, r in var.existing_egress_rules : i => r
  } : {}

  managed_prefix_list_id = one(aws_ec2_managed_prefix_list.this[*].id)
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${var.name}-vpc" })
}

###############################################################################
# Security group (new-group path)
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_new_security_group ? 1 : 0

  name_prefix            = "${var.name}-"
  description            = var.security_group_description
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(var.tags, { Name = var.name })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Rules for the newly created security group
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "new" {
  for_each = local.new_ingress_rule_map

  security_group_id = aws_security_group.this[0].id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "module" ? local.managed_prefix_list_id : each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  description = each.value.description

  tags = merge(var.tags, { Name = "${var.name}-new-ingress-${each.key}" })
}

resource "aws_vpc_security_group_egress_rule" "new" {
  for_each = local.new_egress_rule_map

  security_group_id = aws_security_group.this[0].id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "module" ? local.managed_prefix_list_id : each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  description = each.value.description

  tags = merge(var.tags, { Name = "${var.name}-new-egress-${each.key}" })
}

###############################################################################
# Rules for the caller-supplied existing security group
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.existing_ingress_rule_map

  security_group_id = var.existing_security_group_id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "module" ? local.managed_prefix_list_id : each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  description = each.value.description

  tags = merge(var.tags, { Name = "${var.name}-existing-ingress-${each.key}" })
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.existing_egress_rule_map

  security_group_id = var.existing_security_group_id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "module" ? local.managed_prefix_list_id : each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  description = each.value.description

  tags = merge(var.tags, { Name = "${var.name}-existing-egress-${each.key}" })
}

###############################################################################
# Optional customer-managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for i, c in var.prefix_list_entries : i => c }

    content {
      cidr        = entry.value
      description = "prefix-list-entry-${entry.key}"
    }
  }

  tags = merge(var.tags, { Name = local.prefix_list_name })
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the security group managed by this module, or the caller-supplied existing security group."
  value = var.create ? (
    var.create_new_security_group ? try(aws_security_group.this[0].id, null) : (
      var.existing_security_group_id != "" ? var.existing_security_group_id : null
    )
  ) : null
}

output "security_group_arn" {
  description = "ARN of the security group managed by this module, or null when the module does not manage one."
  value       = var.create && var.create_new_security_group ? try(aws_security_group.this[0].arn, null) : null
}

output "prefix_list_id" {
  description = "ID of the customer-managed prefix list, or the first caller-supplied existing prefix list ID."
  value = var.create ? (
    length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids[0] : try(aws_ec2_managed_prefix_list.this[0].id, null)
  ) : null
}

output "prefix_list_arn" {
  description = "ARN of the customer-managed prefix list created by this module, or null when no prefix list is managed here."
  value       = local.create_prefix_list ? try(aws_ec2_managed_prefix_list.this[0].arn, null) : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name applied to all resources via the Environment tag."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  ssm_prefixes = {
    files_invitations = "/file-service/dynamodb/invitations"
    files             = "/file-service/dynamodb/files"
    hashes            = "/hashes-service/dynamodb/hashes"
    storage           = "/file-service/dynamodb/storage"
    wallets           = "/wallet-service/dynamodb/wallets"
  }
}

