terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Input variables - every variable has a default so applies are non-interactive
###############################################################################

variable "name" {
  description = "Explicit identifier used for the AWS Transfer Family server and its supporting resources. Falls back to a two-word random pet name when empty."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Transfer server endpoint type: PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled on the Transfer server (SFTP, FTPS, AS2)."
  type        = list(string)
  default     = ["SFTP"]
}

variable "identity_provider_type" {
  description = "Identity provider type used by the Transfer server."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, AWS_LAMBDA."
  }
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role used by the Transfer server for CloudWatch logging. A dedicated role is created when empty."
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "ACM certificate ARN used by the server when the FTPS protocol is enabled."
  type        = string
  default     = null
}

variable "login_banner" {
  description = "Login banner shown to clients after successful authentication."
  type        = string
  default     = null
}

variable "security_policy_name" {
  description = "Security policy applied to the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "host_key" {
  description = "RSA private key that identifies the server. AWS generates one when omitted."
  type        = string
  default     = null
  sensitive   = true
}

variable "cloudwatch_log_group_name" {
  description = "Name or ARN of an existing CloudWatch log group that receives the Transfer server logs. A dedicated log group is created when null."
  type        = string
  default     = null
}

variable "logging_kms_key_arn" {
  description = "ARN of an existing KMS key used to encrypt the Transfer server log group. A dedicated key is created when null."
  type        = string
  default     = null
}

variable "user_log_group_arn" {
  description = "ARN of an additional CloudWatch log group used as the structured logging destination."
  type        = string
  default     = null
}

variable "protocol_details" {
  description = "Optional Transfer server protocol details: passive IP, set-stat option and TLS session resumption mode."
  type = object({
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "as2_transports" {
  description = "AS2 transports enabled on the server (for example [\"AS2\"]). Only used when the AS2 protocol is enabled."
  type        = list(string)
  default     = []
}

variable "vpc_id" {
  description = "VPC ID hosting the Transfer server. Required for VPC / VPC_ENDPOINT endpoint types."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs used by the Transfer server and the Elastic IPs created for it."
  type        = list(string)
  default     = []
}

variable "vpc_endpoint_id" {
  description = "VPC endpoint ID used when endpoint_type is VPC_ENDPOINT."
  type        = string
  default     = ""
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID used to publish the Transfer server DNS record. No record is created when empty."
  type        = string
  default     = ""
}

variable "route53_zone_name" {
  description = "Route 53 hosted zone name used to build the fully qualified record name (for example example.com)."
  type        = string
  default     = ""
}

variable "record_name" {
  description = "Sub-domain label of the Route 53 CNAME record pointing at the Transfer server endpoint."
  type        = string
  default     = "sftp"
}

variable "sftp_users" {
  description = "Map of SFTP users keyed by user name. Each user gets an IAM role, an S3 scoped policy, a Transfer user and optional SSH keys."
  type = map(object({
    home_bucket         = string
    home_directory      = optional(string, "/")
    home_directory_type = optional(string, "PATH")
  }))
  default = {}
}

variable "sftp_user_public_keys" {
  description = "Map of SSH public keys keyed by SFTP user name. Users without an entry are skipped."
  type        = map(list(string))
  default     = {}
}

variable "api_gateway_url" {
  description = "API Gateway invocation URL used when identity_provider_type is API_GATEWAY."
  type        = string
  default     = ""
}

variable "api_gateway_invocation_role_arn" {
  description = "ARN of the IAM role the Transfer server assumes to invoke the API Gateway authorizer."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags merged into the common tag set applied to every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources - static provider metadata only
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Random pet fallback name
###############################################################################

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

###############################################################################
# Locals - resolved names, ARNs and per-user values
###############################################################################

locals {
  server_name = var.name != "" ? var.name : random_pet.server_name.id

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  is_vpc_endpoint_type = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)
  is_vpc               = var.endpoint_type == "VPC"

  create_logging_role                = var.logging_role_arn == ""
  create_api_gateway_cloudwatch_role = var.identity_provider_type == "API_GATEWAY"
  create_customer_managed_kms_key    = var.logging_kms_key_arn == null
  create_transfer_log_group          = var.cloudwatch_log_group_name == null

  common_tags = merge(
    {
      ManagedBy   = "Terraform"
      Application = "AWS Transfer Family"
      Name        = local.server_name
    },
    var.tags
  )

  effective_logging_role_arn = local.create_logging_role ? aws_iam_role.logging[0].arn : var.logging_role_arn

  effective_kms_key_arn = local.create_customer_managed_kms_key ? aws_kms_key.transfer_logs[0].arn : var.logging_kms_key_arn

  effective_log_group_arn = local.create_transfer_log_group ? aws_cloudwatch_log_group.transfer[0].arn : (
    startswith(var.cloudwatch_log_group_name, "arn:") ? var.cloudwatch_log_group_name : "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${var.cloudwatch_log_group_name}"
  )

  structured_log_destinations = compact([coalesce(var.user_log_group_arn, local.effective_log_group_arn)])

  has_protocol_details = (
    length(var.as2_transports) > 0 ||
    var.protocol_details.passive_ip != null ||
    var.protocol_details.set_stat_option != null ||
    var.protocol_details.tls_session_resumption_mode != null
  )

  sftp_user_home_prefixes = {
    for user_name, user in var.sftp_users : user_name => trimsuffix(trimprefix(user.home_directory, "/"), "/")
  }

  sftp_users_normalized = {
    for user_name, user in var.sftp_users : user_name => {
      home_prefix         = local.sftp_user_home_prefixes[user_name]
      home_directory      = local.sftp_user_home_prefixes[user_name] == "" ? "/${user.home_bucket}" : "/${user.home_bucket}/${local.sftp_user_home_prefixes[user_name]}"
      home_directory_type = user.home_directory_type
      bucket_arn          = "arn:${local.partition}:s3:::${user.home_bucket}"
      objects_arn         = local.sftp_user_home_prefixes[user_name] == "" ? "arn:${local.partition}:s3:::${user.home_bucket}/*" : "arn:${local.partition}:s3:::${user.home_bucket}/${local.sftp_user_home_prefixes[user_name]}/*"
    }
  }

  sftp_ssh_key_list = flatten([
    for user_name, public_keys in var.sftp_user_public_keys : [
      for idx, public_key in public_keys : {
        key        = "${user_name}-${idx}"
        user_name  = user_name
        public_key = trimspace(public_key)
      }
    ]
    if contains(keys(var.sftp_users), user_name)
  ])

  sftp_ssh_keys = { for entry in local.sftp_ssh_key_list : entry.key => entry }

  record_fqdn = var.route53_zone_name != "" ? "${var.record_name}.${var.route53_zone_name}" : var.record_name
}

###############################################################################
# IAM assume role policies
###############################################################################

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "AllowTransferServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "api_gateway_assume_role" {
  statement {
    sid     = "AllowApiGatewayToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

###############################################################################
# Transfer server logging role
###############################################################################

resource "aws_iam_role" "logging" {
  count = local.create_logging_role ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer-logging"
  })
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = local.create_logging_role ? 1 : 0

  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# API Gateway CloudWatch logging role (only for API_GATEWAY identity provider)
###############################################################################

resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = local.create_api_gateway_cloudwatch_role ? 1 : 0

  name               = "${local.server_name}-apigw-cloudwatch"
  assume_role_policy = data.aws_iam_policy_document.api_gateway_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-apigw-cloudwatch"
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_cloudwatch" {
  count = local.create_api_gateway_cloudwatch_role ? 1 : 0

  role       = aws_iam_role.api_gateway_cloudwatch[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = local.create_api_gateway_cloudwatch_role ? 1 : 0

  name = "${local.server_name}-apigw-cloudwatch-logs"
  role = aws_iam_role.api_gateway_cloudwatch[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteApiGatewayAndTransferLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = [
          "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/api-gateway/*",
          "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/api-gateway/*:*",
          local.effective_log_group_arn,
          "${local.effective_log_group_arn}:*"
        ]
      }
    ]
  })
}

resource "aws_api_gateway_account" "this" {
  count = local.create_api_gateway_cloudwatch_role ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch[0].arn
}

###############################################################################
# Logging encryption key and log group
###############################################################################

data "aws_iam_policy_document" "transfer_logs_kms" {
  count = local.create_customer_managed_kms_key ? 1 : 0

  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsToUseTheKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt*",
      "kms:Describe*",
      "kms:Encrypt*",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }
}

resource "aws_kms_key" "transfer_logs" {
  count = local.create_customer_managed_kms_key ? 1 : 0

  description             = "KMS key used to encrypt CloudWatch logs for the AWS Transfer Family server ${local.server_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.transfer_logs_kms[0].json

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer-logs"
  })
}

resource "aws_cloudwatch_log_group" "transfer" {
  count = local.create_transfer_log_group ? 1 : 0

  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = 90
  kms_key_id        = local.effective_kms_key_arn

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer-logs"
  })
}

###############################################################################
# Networking for VPC / VPC_ENDPOINT endpoint types (none for PUBLIC)
###############################################################################

resource "aws_security_group" "transfer" {
  count = local.is_vpc_endpoint_type ? 1 : 0

  name_prefix = "${local.server_name}-transfer-"
  description = "Security group for the AWS Transfer Family server ${local.server_name}"
  vpc_id      = var.vpc_id != "" ? var.vpc_id : null

  ingress {
    description = "SFTP client access from the internet"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer"
  })
}

resource "aws_eip" "transfer" {
  for_each = local.is_vpc ? toset(var.subnet_ids) : toset([])

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name     = "${local.server_name}-eip"
    SubnetId = each.key
  })
}

###############################################################################
# Transfer Family server
###############################################################################

resource "aws_transfer_server" "this" {
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  identity_provider_type = var.identity_provider_type
  security_policy_name   = var.security_policy_name
  logging_role           = local.effective_logging_role_arn
  certificate            = var.certificate_arn
  host_key               = var.host_key

  post_authentication_login_banner = var.login_banner

  structured_log_destinations = local.structured_log_destinations

  url             = var.identity_provider_type == "API_GATEWAY" && var.api_gateway_url != "" ? var.api_gateway_url : null
  invocation_role = var.identity_provider_type == "API_GATEWAY" && var.api_gateway_invocation_role_arn != "" ? var.api_gateway_invocation_role_arn : null

  dynamic "endpoint_details" {
    for_each = local.is_vpc_endpoint_type ? [1] : []

    content {
      vpc_id                 = local.is_vpc ? (var.vpc_id != "" ? var.vpc_id : null) : null
      subnet_ids             = length(var.subnet_ids) > 0 ? var.subnet_ids : null
      security_group_ids     = [aws_security_group.transfer[0].id]
      address_allocation_ids = local.is_vpc && length(var.subnet_ids) > 0 ? [for subnet_id in var.subnet_ids : aws_eip.transfer[subnet_id].id] : null
      vpc_endpoint_id        = var.endpoint_type == "VPC_ENDPOINT" && var.vpc_endpoint_id != "" ? var.vpc_endpoint_id : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.has_protocol_details ? [1] : []

    content {
      as2_transports              = length(var.as2_transports) > 0 ? var.as2_transports : null
      passive_ip                  = var.protocol_details.passive_ip
      set_stat_option             = var.protocol_details.set_stat_option
      tls_session_resumption_mode = var.protocol_details.tls_session_resumption_mode
    }
  }

  tags = merge(local.common_tags, {
    Name = local.server_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.logging
  ]
}

###############################################################################
# Per-user IAM role, policy, Transfer user and SSH keys
###############################################################################

resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users

  name               = "${local.server_name}-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = merge(local.common_tags, {
    Name         = "${local.server_name}-${each.key}"
    SftpUserName = each.key
  })
}

resource "aws_iam_role_policy" "sftp_user" {
  for_each = var.sftp_users

  name = "${local.server_name}-${each.key}-s3"
  role = aws_iam_role.sftp_user[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListUserHomeBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          local.sftp_users_normalized[each.key].bucket_arn
        ]
      },
      {
        Sid    = "AccessUserHomeObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = [
          local.sftp_users_normalized[each.key].objects_arn
        ]
      }
    ]
  })
}

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.sftp_user[each.key].arn
  home_directory      = local.sftp_users_normalized[each.key].home_directory
  home_directory_type = local.sftp_users_normalized[each.key].home_directory_type

  tags = merge(local.common_tags, {
    Name = each.key
  })
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.sftp_ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.value.user_name].user_name
  body      = trimspace(each.value.public_key)
}

###############################################################################
# Optional Route 53 CNAME mapping
###############################################################################

resource "aws_route53_record" "transfer" {
  count = var.route53_zone_id != "" ? 1 : 0

  zone_id         = var.route53_zone_id
  name            = local.record_fqdn
  type            = "CNAME"
  ttl             = 300
  records         = [aws_transfer_server.this.endpoint]
  allow_overwrite = true
}

###############################################################################
# Outputs
###############################################################################

output "transfer_server_id" {
  description = "Identifier of the AWS Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "transfer_server_arn" {
  description = "ARN of the AWS Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "transfer_server_endpoint" {
  description = "Endpoint used by SFTP/FTPS clients to connect to the server."
  value       = aws_transfer_server.this.endpoint
}

output "transfer_server_name" {
  description = "Resolved name of the AWS Transfer Family server."
  value       = local.server_name
}

output "logging_role_arn" {
  description = "ARN of the IAM role used by the server for CloudWatch logging."
  value       = local.effective_logging_role_arn
}

output "structured_log_destinations" {
  description = "CloudWatch log group ARNs receiving structured logs."
  value       = local.structured_log_destinations
}

output "sftp_user_names" {
  description = "Names of the provisioned SFTP users."
  value       = keys(var.sftp_users)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where the VPC stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC, also used as the prefix for all child resource names."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of availability zones to use. Null means use all available AZs in the region."
  type        = number
  default     = null

  validation {
    condition     = var.az_count == null || try(var.az_count >= 1 && var.az_count <= 8, false)
    error_message = "az_count must be null (use all available AZs) or a number between 1 and 8."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets (and their IGW, route table and NACL)."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets (and their route tables and NACL)."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags merged into every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  az_count     = coalesce(var.az_count, length(data.aws_availability_zones.available.names))
  selected_azs = slice(data.aws_availability_zones.available.names, 0, min(local.az_count, length(data.aws_availability_zones.available.names)))

  public_subnet_cidrs = var.create_public_subnets ? {
    for idx, az in local.selected_azs : az => cidrsubnet(var.vpc_cidr, 4, idx)
  } : {}

  private_subnet_cidrs = var.create_private_subnets ? {
    for idx, az in local.selected_azs : az => cidrsubnet(var.vpc_cidr, 4, idx + 8)
  } : {}

  create_nat_gateway = var.create_nat_gateway && length(local.public_subnet_cidrs) > 0

  common_tags = merge(var.tags, {
    ManagedBy = "Terraform"
    Vpc       = var.vpc_name
  })
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  for_each = local.public_subnet_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${each.key}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnet_cidrs

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value
  availability_zone = each.key

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${each.key}"
    Tier = "private"
  })
}

###############################################################################
# Internet gateway and public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  count  = length(local.public_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

resource "aws_route_table" "public" {
  count  = length(local.public_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnet_cidrs

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# NAT gateway and private routing
###############################################################################

resource "aws_eip" "nat" {
  count  = local.create_nat_gateway ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.create_nat_gateway ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[local.selected_azs[0]].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [
    aws_internet_gateway.main,
    aws_route_table_association.public,
  ]
}

resource "aws_route_table" "private" {
  for_each = local.private_subnet_cidrs

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt-${each.key}"
  })
}

resource "aws_route" "private_nat" {
  for_each = local.create_nat_gateway ? local.private_subnet_cidrs : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnet_cidrs

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  count  = length(local.public_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  subnet_ids = [for subnet in aws_subnet.public : subnet.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 130
    protocol   = "udp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  ingress {
    rule_no    = 140
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 130
    protocol   = "udp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  egress {
    rule_no    = 140
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl" "private" {
  count  = length(local.private_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  subnet_ids = [for subnet in aws_subnet.private : subnet.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 130
    protocol   = "udp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  ingress {
    rule_no    = 140
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 130
    protocol   = "udp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  egress {
    rule_no    = 140
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 53
    to_port    = 53
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}
###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "Map of availability zone to public subnet ID."
  value       = { for az, subnet in aws_subnet.public : az => subnet.id }
}

output "private_subnet_ids" {
  description = "Map of availability zone to private subnet ID."
  value       = { for az, subnet in aws_subnet.private : az => subnet.id }
}

output "internet_gateway_id" {
  description = "ID of the internet gateway (null when public subnets are disabled)."
  value       = length(aws_internet_gateway.main) > 0 ? aws_internet_gateway.main[0].id : null
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway (null when it is disabled)."
  value       = length(aws_nat_gateway.main) > 0 ? aws_nat_gateway.main[0].id : null
}

output "public_route_table_id" {
  description = "ID of the public route table (null when public subnets are disabled)."
  value       = length(aws_route_table.public) > 0 ? aws_route_table.public[0].id : null
}

output "private_route_table_ids" {
  description = "Map of availability zone to private route table ID."
  value       = { for az, rt in aws_route_table.private : az => rt.id }
}

output "public_network_acl_id" {
  description = "ID of the public network ACL (null when public subnets are disabled)."
  value       = length(aws_network_acl.public) > 0 ? aws_network_acl.public[0].id : null
}

output "private_network_acl_id" {
  description = "ID of the private network ACL (null when private subnets are disabled)."
  value       = length(aws_network_acl.private) > 0 ? aws_network_acl.private[0].id : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # NOTE: no backend block and no provider block are declared here; the
  # deployment harness injects the provider configuration and remote state.
}

###############################################################################
# Variables (all have defaults so `terraform apply` runs unattended)
###############################################################################

variable "tags" {
  description = "Common tags applied to every resource created by this stack."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Project   = "three-tier-dualstack"
  }
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the main VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Whether the VPC (and its subnets/routes) is dual-stack with Amazon-provided IPv6 CIDRs."
  type        = bool
  default     = true
}

variable "sn_details" {
  description = "Subnet definitions: name, index into the available AZ names, and public/private flag."
  type = list(object({
    name      = string
    az_index  = number
    is_public = bool
  }))
  default = [
    { name = "web-1a", az_index = 0, is_public = true },
    { name = "app-1a", az_index = 0, is_public = false },
    { name = "database-1a", az_index = 0, is_public = false },
    { name = "reserved-1a", az_index = 0, is_public = false },
    { name = "web-1b", az_index = 1, is_public = true },
    { name = "app-1b", az_index = 1, is_public = false },
    { name = "database-1b", az_index = 1, is_public = false },
    { name = "reserved-1b", az_index = 1, is_public = false },
    { name = "web-1c", az_index = 2, is_public = true },
    { name = "app-1c", az_index = 2, is_public = false },
    { name = "database-1c", az_index = 2, is_public = false },
    { name = "reserved-1c", az_index = 2, is_public = false },
  ]
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      ManagedBy = "terraform"
    },
    var.tags
  )

  # Deterministic map keyed by subnet name so for_each (never count) is stable.
  subnet_map = { for s in var.sn_details : s.name => s }

  public_subnets  = { for k, v in local.subnet_map : k => v if v.is_public }
  private_subnets = { for k, v in local.subnet_map : k => v if !v.is_public }
}

###############################################################################
# Availability zone metadata (static provider lookup only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

###############################################################################
# CIDR calculation modules
###############################################################################

# /20 IPv4 allocations carved out of 10.16.0.0/16 (4 additional bits).
module "subnets_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.vpc_cidr

  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = 4
    }
  ]
}

###############################################################################
# VPC (dual-stack)
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    }
  )
}

# /64 IPv6 allocations carved out of the Amazon-provided VPC IPv6 CIDR block
# (8 additional bits). Only instantiated when IPv6 is enabled.
module "subnets_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  count = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block

  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = 8
    }
  ]
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = module.subnets_ipv4.network_cidr_blocks[each.key]
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  ipv6_cidr_block = var.is_ipv6_enabled ? try(module.subnets_ipv6[0].network_cidr_blocks[each.key], null) : null

  assign_ipv6_address_on_creation = var.is_ipv6_enabled

  # Public IPs are never auto-assigned on launch; instances must opt in
  # explicitly, so no subnet exposes instances with a public address by default.
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = each.value.name
      Tier = each.value.is_public ? "public" : "private"
    }
  )
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "main-igw-vpc-${aws_vpc.main.id}"
    }
  )
}

###############################################################################
# Public route table (IPv4 + IPv6 default routes to the Internet Gateway)
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "public-rt-web"
    }
  )
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

# Only subnets flagged public are associated with the public route table.
# Private subnets intentionally have no route to the Internet Gateway.
resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups (no inline ingress/egress blocks; default egress is revoked
# by Terraform because no egress blocks are declared)
###############################################################################

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier: TLS from the internet, SSH only from the VPC, TLS egress to the app tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "web_sg"
    }
  )
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "App tier: TLS from the web tier, TLS egress to the database tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "app_sg"
    }
  )
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Database tier: TLS from the app tier only, no CIDR-based ingress and no egress."
  vpc_id      = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "db_sg"
    }
  )
}

###############################################################################
# web_sg rules
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "web_https_ipv4" {
  security_group_id = aws_security_group.web_sg.id
  description       = "TLS from anywhere (IPv4)"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = "0.0.0.0/0"

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "web_https_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  security_group_id = aws_security_group.web_sg.id
  description       = "TLS from anywhere (IPv6)"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv6         = "::/0"

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "web_ssh_vpc" {
  security_group_id = aws_security_group.web_sg.id
  description       = "SSH from within the VPC IPv4 CIDR only"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "web_to_app_https" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "TLS to the app tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id

  tags = local.common_tags
}

###############################################################################
# app_sg rules
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "app_from_web_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS from the web tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.web_sg.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "app_to_db_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS to the database tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.db_sg.id

  tags = local.common_tags
}

###############################################################################
# db_sg rules
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "db_from_app_https" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "TLS from the app tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id

  tags = local.common_tags
}

# No egress rules are declared for db_sg on purpose: the AWS default
# allow-all egress rule is revoked, keeping the database tier egress-minimal.

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the main VPC (null when IPv6 is disabled)."
  value       = var.is_ipv6_enabled ? aws_vpc.main.ipv6_cidr_block : null
}

output "public_subnet_ids" {
  description = "Map of public subnet name to subnet ID."
  value       = { for k, v in local.public_subnets : k => aws_subnet.this[k].id }
}

output "private_subnet_ids" {
  description = "Map of private subnet name to subnet ID."
  value       = { for k, v in local.private_subnets : k => aws_subnet.this[k].id }
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the main VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table used by the web tier subnets."
  value       = aws_route_table.public.id
}

output "web_security_group_id" {
  description = "ID of the web tier security group."
  value       = aws_security_group.web_sg.id
}

output "app_security_group_id" {
  description = "ID of the app tier security group."
  value       = aws_security_group.app_sg.id
}

output "db_security_group_id" {
  description = "ID of the database tier security group."
  value       = aws_security_group.db_sg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name prefix applied to every resource created by this module."
  type        = string
  default     = "vpc"
}

variable "create_vpc" {
  description = "Controls if the VPC and all of its associated resources are created."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames support in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS resolution support in the VPC."
  type        = bool
  default     = true
}

variable "map_public_ip_on_launch" {
  description = "Auto-assign public IP addresses to instances launched in public subnets."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway is created for the public subnets."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways (and Elastic IPs) are provisioned for private subnet egress."
  type        = bool
  default     = false
}

variable "azs" {
  description = "Optional list of availability zone names or IDs. Defaults to all available AZs in the region."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "List of CIDR blocks used for the public (internet facing) subnet tier."
  type        = list(string)
  default = [
    "10.0.0.0/24",
    "10.0.1.0/24",
    "10.0.2.0/24",
  ]
}

variable "private_subnets" {
  description = "List of CIDR blocks used for the private (NAT egress) subnet tier."
  type        = list(string)
  default = [
    "10.0.10.0/24",
    "10.0.11.0/24",
    "10.0.12.0/24",
  ]
}

variable "intra_subnets" {
  description = "List of CIDR blocks used for the isolated intra subnet tier (no external routes)."
  type        = list(string)
  default = [
    "10.0.20.0/24",
    "10.0.21.0/24",
    "10.0.22.0/24",
  ]
}

variable "public_subnet_suffix" {
  description = "Suffix appended to generated public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix appended to generated private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix appended to generated intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Optional explicit list of Name tags for the public subnets. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit list of Name tags for the private subnets. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit list of Name tags for the intra subnets. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags merged into every resource created by this module."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  create_public_subnets_tier = var.create_vpc && length(var.public_subnets) > 0
  create_internet_gateway    = local.create_public_subnets_tier && var.create_igw

  create_nat_gateways = (
    var.create_vpc
    && var.enable_nat_gateway
    && local.create_public_subnets_tier
    && length(var.private_subnets) > 0
  )

  nat_gateway_count = local.create_nat_gateways ? min(length(var.public_subnets), length(var.private_subnets)) : 0

  public_subnet_names = length(var.public_subnet_names) > 0 ? var.public_subnet_names : [
    for i in range(length(var.public_subnets)) :
    "${var.name}-${var.public_subnet_suffix}-${local.azs[i % length(local.azs)]}"
  ]

  private_subnet_names = length(var.private_subnet_names) > 0 ? var.private_subnet_names : [
    for i in range(length(var.private_subnets)) :
    "${var.name}-${var.private_subnet_suffix}-${local.azs[i % length(local.azs)]}"
  ]

  intra_subnet_names = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names : [
    for i in range(length(var.intra_subnets)) :
    "${var.name}-${var.intra_subnet_suffix}-${local.azs[i % length(local.azs)]}"
  ]

  common_tags = merge(
    {
      ManagedBy = "terraform"
    },
    var.tags
  )
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    local.common_tags,
    {
      Name = var.name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Subnets - public tier
################################################################################

resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnets) : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = element(local.public_subnet_names, count.index)
      Tier = var.public_subnet_suffix
    }
  )
}

################################################################################
# Subnets - private tier
################################################################################

resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(
    local.common_tags,
    {
      Name = element(local.private_subnet_names, count.index)
      Tier = var.private_subnet_suffix
    }
  )
}

################################################################################
# Subnets - isolated intra tier
################################################################################

resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = var.intra_subnets[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(
    local.common_tags,
    {
      Name = element(local.intra_subnet_names, count.index)
      Tier = var.intra_subnet_suffix
    }
  )
}

################################################################################
# Internet Gateway (public tier only)
################################################################################

resource "aws_internet_gateway" "main" {
  count = local.create_internet_gateway ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-igw"
      Tier = var.public_subnet_suffix
    }
  )
}

################################################################################
# Public routing
################################################################################

resource "aws_route_table" "public" {
  count = local.create_internet_gateway ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.public_subnet_suffix}-rt"
      Tier = var.public_subnet_suffix
    }
  )
}

resource "aws_route" "public_internet_access" {
  count = local.create_internet_gateway ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT gateways (Elastic IPs + gateways)
################################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-nat-eip-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-nat-${count.index + 1}"
      Tier = var.public_subnet_suffix
    }
  )

  depends_on = [aws_internet_gateway.main]
}

################################################################################
# Private routing (one route table per private subnet)
################################################################################

resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.private_subnet_suffix}-rt-${count.index + 1}"
      Tier = var.private_subnet_suffix
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? length(aws_route_table.private) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index % length(aws_nat_gateway.main)].id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

################################################################################
# Intra routing (isolated - VPC local route only)
################################################################################

resource "aws_route_table" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.intra_subnet_suffix}-rt-${count.index + 1}"
      Tier = var.intra_subnet_suffix
    }
  )
}

resource "aws_route_table_association" "intra" {
  count = length(aws_subnet.intra)

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "api_type" {
  description = "API type to provision: 'http' (API Gateway v2) or 'rest' (API Gateway v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  description = "Name of the API."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Deployment environment name used for stage naming."
  type        = string
  default     = "dev"
}

variable "domain_name" {
  description = "Custom domain name for the API."
  type        = string
  default     = "example.com"
}

variable "vpc_link_enabled" {
  description = "Whether to provision an API Gateway VPC link to the internal NLB."
  type        = bool
  default     = false
}

variable "target_group_port" {
  description = "TCP port for the NLB target group and listener."
  type        = number
  default     = 443
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "http_routes" {
  description = "List of HTTP API route keys (e.g. 'GET /items')."
  type        = list(string)
  default = [
    "GET /items",
    "POST /items",
    "GET /items/{id}"
  ]
}

variable "rest_routes" {
  description = "Map of REST API root path parts to method configuration."
  type = map(object({
    method          = string
    path_parameters = optional(map(string), {})
  }))
  default = {
    "items" = {
      method = "GET"
    }
    "orders" = {
      method = "POST"
    }
  }
}

variable "enable_authorizer" {
  description = "Whether to provision a custom Lambda authorizer for the REST API."
  type        = bool
  default     = false
}

variable "enable_ip_restriction" {
  description = "Whether to attach an IP source restriction resource policy to the REST API."
  type        = bool
  default     = false
}

variable "allowed_ip_ranges" {
  description = "CIDR ranges allowed to invoke the REST API when IP restriction is enabled."
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

locals {
  name_prefix = "${var.api_name}-${var.environment}"
  stage_name  = "${var.environment}-stage"
  is_http     = var.api_type == "http"
  is_rest     = var.api_type == "rest"

  tags = {
    Project     = var.api_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "nlb" {
  name        = "${local.name_prefix}-nlb-sg"
  description = "Security group for the internal Network Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Inbound TCP from within the VPC"
    from_port   = var.target_group_port
    to_port     = var.target_group_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Forward to the internal Application Load Balancer"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nlb-sg"
  })
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for the internal Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from the Network Load Balancer"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.nlb.id]
  }

  egress {
    description = "Outbound within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

# ---------------------------------------------------------------------------
# Route 53 + ACM (regional TLS 1.2 certificate)
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "this" {
  name = var.domain_name

  tags = merge(local.tags, {
    Name = var.domain_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_acm_certificate" "this" {
  domain_name               = var.domain_name
  subject_alternative_names = ["*.${var.domain_name}"]
  validation_method         = "DNS"

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.this.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = aws_route53_zone.this.zone_id
}

resource "aws_acm_certificate_validation" "this" {
  certificate_arn         = aws_acm_certificate.this.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

# ---------------------------------------------------------------------------
# Internal ALB (target of the NLB target group)
# ---------------------------------------------------------------------------

resource "aws_lb" "alb" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_listener" "alb" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate_validation.this.certificate_arn

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# Internal NLB (fronts the ALB)
# ---------------------------------------------------------------------------

resource "aws_lb_target_group" "nlb" {
  name                 = "${local.name_prefix}-nlb-tg"
  port                 = var.target_group_port
  protocol             = "TCP"
  target_type          = "alb"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = "/"
    matcher             = "200"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
    timeout             = 10
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nlb-tg"
  })
}

resource "aws_lb_target_group_attachment" "nlb" {
  target_group_arn = aws_lb_target_group.nlb.arn
  target_id        = aws_lb.alb.arn
  port             = 443
}

resource "aws_lb" "nlb" {
  name               = "${local.name_prefix}-nlb"
  internal           = true
  load_balancer_type = "network"
  security_groups    = [aws_security_group.nlb.id]
  subnets            = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nlb"
  })
}

resource "aws_lb_listener" "nlb" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = var.target_group_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb.arn
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# API Gateway VPC links (conditional)
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.is_http && var.vpc_link_enabled ? 1 : 0
  name               = "${local.name_prefix}-vpc-link"
  security_group_ids = [aws_security_group.nlb.id]
  subnet_ids         = aws_subnet.private[*].id

  tags = local.tags
}

resource "aws_api_gateway_vpc_link" "this" {
  count       = local.is_rest && var.vpc_link_enabled ? 1 : 0
  name        = "${local.name_prefix}-vpc-link"
  description = "VPC link for the ${var.api_name} REST API"
  target_arns = [aws_lb.nlb.arn]

  tags = local.tags
}

# ---------------------------------------------------------------------------
# Backend Lambda (shared integration target)
# ---------------------------------------------------------------------------

data "archive_file" "backend" {
  type        = "zip"
  output_path = "${path.module}/backend.zip"

  source {
    filename = "index.py"
    content  = <<-PY
      import json

      def handler(event, context):
          return {
              "statusCode": 200,
              "headers": {"Content-Type": "application/json"},
              "body": json.dumps({
                  "message": "ok",
                  "path": event.get("path", "/"),
                  "method": event.get("httpMethod", event.get("requestContext", {}).get("http", {}).get("method", "GET")),
              }),
          }
    PY
  }
}

resource "aws_iam_role" "backend" {
  name = "${local.name_prefix}-backend-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backend_logs" {
  role       = aws_iam_role.backend.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "backend" {
  function_name    = "${local.name_prefix}-backend"
  role             = aws_iam_role.backend.arn
  handler          = "index.handler"
  runtime          = "python3.12"
  filename         = data.archive_file.backend.output_path
  source_code_hash = data.archive_file.backend.output_base64sha256
  timeout          = 30

  tags = local.tags

  depends_on = [aws_iam_role_policy_attachment.backend_logs]
}

# ---------------------------------------------------------------------------
# HTTP API (API Gateway v2)
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "http" {
  count         = local.is_http ? 1 : 0
  name          = var.api_name
  protocol_type = "HTTP"

  tags = local.tags
}

resource "aws_apigatewayv2_integration" "http" {
  count = local.is_http ? 1 : 0

  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.backend.invoke_arn
  integration_method     = "POST"
  payload_format_version = "2.0"
  connection_type        = var.vpc_link_enabled ? "VPC_LINK" : "INTERNET"
  connection_id          = var.vpc_link_enabled ? aws_apigatewayv2_vpc_link.http[0].id : null
}

resource "aws_apigatewayv2_route" "http" {
  for_each = local.is_http ? toset(var.http_routes) : toset([])

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.value
  target    = "integrations/${aws_apigatewayv2_integration.http[0].id}"

  authorization_type = "NONE"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  tags = local.tags
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.is_http ? 1 : 0
  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.this.certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = local.tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_alias" {
  count   = local.is_http && var.domain_name != "" ? 1 : 0
  zone_id = aws_route53_zone.this.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_lambda_permission" "http_api" {
  count         = local.is_http ? 1 : 0
  statement_id  = "AllowExecutionFromHTTPAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/*/*"
}

# ---------------------------------------------------------------------------
# REST API (API Gateway v1)
# ---------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "REST API managed by Terraform"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.tags
}

resource "aws_api_gateway_resource" "rest" {
  for_each    = local.is_rest ? var.rest_routes : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.key
}

resource "aws_api_gateway_method" "rest" {
  for_each    = local.is_rest ? var.rest_routes : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.key].id
  http_method = each.value.method

  authorization = local.is_rest && var.enable_authorizer ? "CUSTOM" : "NONE"
  authorizer_id = local.is_rest && var.enable_authorizer ? aws_api_gateway_authorizer.this[0].id : null

  request_parameters = each.value.path_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each    = local.is_rest ? var.rest_routes : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.key].id
  http_method = aws_api_gateway_method.rest[each.key].http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.backend.invoke_arn

  connection_type = var.vpc_link_enabled ? "VPC_LINK" : "INTERNET"
  connection_id   = var.vpc_link_enabled ? aws_api_gateway_vpc_link.this[0].id : null
}

resource "aws_api_gateway_deployment" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.rest,
      aws_api_gateway_method.rest,
      aws_api_gateway_integration.rest,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.rest,
    aws_api_gateway_integration.rest,
  ]
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.is_rest ? 1 : 0
  deployment_id = aws_api_gateway_deployment.rest[0].id
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  stage_name    = local.stage_name

  tags = local.tags
}

# ---------------------------------------------------------------------------
# REST API IP source restriction policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "rest_policy" {
  count = local.is_rest && var.enable_ip_restriction ? 1 : 0

  statement {
    sid    = "AllowFromAllowedIpRanges"
    effect = "Allow"

    actions   = ["execute-api:Invoke"]
    resources = ["${aws_api_gateway_rest_api.rest[0].execution_arn}/*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "IpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ip_ranges
    }
  }

  statement {
    sid    = "DenyAllOtherSources"
    effect = "Deny"

    actions   = ["execute-api:Invoke"]
    resources = ["${aws_api_gateway_rest_api.rest[0].execution_arn}/*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "NotIpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ip_ranges
    }
  }
}

resource "aws_api_gateway_rest_api_policy" "rest" {
  count       = local.is_rest && var.enable_ip_restriction ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  policy      = data.aws_iam_policy_document.rest_policy[0].json
}

# ---------------------------------------------------------------------------
# REST API usage plan, API key and SSM SecureString
# ---------------------------------------------------------------------------

resource "random_password" "api_key" {
  length  = 40
  special = false
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest ? 1 : 0
  name  = "${local.name_prefix}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  throttle_settings {
    burst_limit = 10
    rate_limit  = 20
  }

  quota_settings {
    limit  = 10000
    period = "MONTH"
  }

  tags = local.tags
}

resource "aws_api_gateway_api_key" "rest" {
  count = local.is_rest ? 1 : 0
  name  = "${local.name_prefix}-api-key"
  value = random_password.api_key.result

  tags = local.tags
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count         = local.is_rest ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.is_rest ? 1 : 0
  name  = "/${var.api_name}/${var.environment}/api-key"
  type  = "SecureString"
  value = random_password.api_key.result

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# REST API custom Lambda authorizer (nodejs20.x)
# ---------------------------------------------------------------------------

data "archive_file" "authorizer" {
  count       = local.is_rest && var.enable_authorizer ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/authorizer.zip"

  source {
    filename = "index.js"
    content  = <<-JS
      exports.handler = async (event) => {
        const headers = event.headers || {};
        const authHeader = headers.Authorization || headers.authorization;

        if (!authHeader) {
          throw new Error("Unauthorized");
        }

        return {
          principalId: "api-user",
          policyDocument: {
            Version: "2012-10-17",
            Statement: [
              {
                Action: "execute-api:Invoke",
                Effect: "Allow",
                Resource: event.methodArn,
              },
            ],
          },
        };
      };
    JS
  }
}

resource "aws_iam_role" "authorizer" {
  count = local.is_rest && var.enable_authorizer ? 1 : 0
  name  = "${local.name_prefix}-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "authorizer_logs" {
  count      = local.is_rest && var.enable_authorizer ? 1 : 0
  role       = aws_iam_role.authorizer[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  count            = local.is_rest && var.enable_authorizer ? 1 : 0
  function_name    = "${local.name_prefix}-authorizer"
  role             = aws_iam_role.authorizer[0].arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256
  timeout          = 15

  tags = local.tags

  depends_on = [aws_iam_role_policy_attachment.authorizer_logs]
}

resource "aws_iam_role" "apigw_invoke" {
  count = local.is_rest && var.enable_authorizer ? 1 : 0
  name  = "${local.name_prefix}-apigw-invoke-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "apigw_invoke" {
  count = local.is_rest && var.enable_authorizer ? 1 : 0
  name  = "${local.name_prefix}-apigw-invoke-policy"
  role  = aws_iam_role.apigw_invoke[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = aws_lambda_function.authorizer[0].arn
      }
    ]
  })
}

resource "aws_api_gateway_authorizer" "this" {
  count          = local.is_rest && var.enable_authorizer ? 1 : 0
  name           = "${local.name_prefix}-authorizer"
  rest_api_id    = aws_api_gateway_rest_api.rest[0].id
  authorizer_uri = aws_lambda_function.authorizer[0].invoke_arn
  type           = "REQUEST"

  authorizer_credentials = aws_iam_role.apigw_invoke[0].arn
  identity_source        = "method.request.header.Authorization"
}

resource "aws_lambda_permission" "authorizer" {
  count         = local.is_rest && var.enable_authorizer ? 1 : 0
  statement_id  = "AllowExecutionFromAPIGatewayAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/authorizers/*"
}

resource "aws_lambda_permission" "rest_api" {
  count         = local.is_rest ? 1 : 0
  statement_id  = "AllowExecutionFromRESTAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*/*"
}

# ---------------------------------------------------------------------------
# REST API custom domain
# ---------------------------------------------------------------------------

resource "aws_api_gateway_domain_name" "rest" {
  count           = local.is_rest ? 1 : 0
  domain_name     = var.domain_name
  certificate_arn = aws_acm_certificate_validation.this.certificate_arn
  security_policy = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.tags
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count       = local.is_rest ? 1 : 0
  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest_alias" {
  count   = local.is_rest && var.domain_name != "" ? 1 : 0
  zone_id = aws_route53_zone.this.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

variable "name" {
  description = "Name/prefix used for naming the CloudTrail resources."
  type        = string
  default     = "cloudtrail"
}

variable "cloudtrail_s3_bucket_name" {
  description = "Explicit S3 bucket name for CloudTrail logs. Empty string auto-generates a name."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Force destroy the CloudTrail S3 bucket (deletes all objects) on destroy."
  type        = bool
  default     = true
}

variable "enable_bucket_versioning" {
  description = "Enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period before the KMS key is deleted."
  type        = number
  default     = 30
}

variable "kms_key_alias_prefix" {
  description = "Alias name for the CloudTrail KMS key."
  type        = string
  default     = "alias/cloudtrail"
}

variable "cloudwatch_log_retention_days" {
  description = "Retention period (days) for the CloudTrail CloudWatch Log Group."
  type        = number
  default     = 90
}

variable "enable_log_file_validation" {
  description = "Enable CloudTrail log file validation."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Create a multi-region trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Create an organization trail."
  type        = bool
  default     = false
}

variable "event_selector_read_write_type" {
  description = "Read/write type for the event selector (All, ReadOnly, WriteOnly)."
  type        = string
  default     = "All"
}

variable "include_management_events" {
  description = "Include management events in the event selector."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors for the trail event selector."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight types to enable on the trail."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Create an SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional existing SNS topic ARN for CloudTrail notifications."
  type        = string
  default     = ""
}

variable "kms_decrypt_role_arn" {
  description = "Optional IAM role ARN permitted to decrypt CloudTrail log files."
  type        = string
  default     = ""
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix for CloudTrail log delivery."
  type        = string
  default     = ""
}

resource "random_string" "suffix" {
  length  = 8
  lower   = true
  upper   = false
  special = false
  numeric = true
}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  trail_name     = "${var.name}-trail"
  cloudtrail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"

  effective_bucket_name = (
    var.cloudtrail_s3_bucket_name != ""
    ? var.cloudtrail_s3_bucket_name
    : "${var.name}-cloudtrail-${local.account_id}-${local.region}-${random_string.suffix.result}"
  )

  effective_sns_topic_arn = (
    var.sns_topic_arn != ""
    ? var.sns_topic_arn
    : try(aws_sns_topic.cloudtrail[0].arn, "")
  )

  sns_topic_name = try(aws_sns_topic.cloudtrail[0].name, null)

  kms_optional_statements = (
    var.kms_decrypt_role_arn != ""
    ? [{
      Sid       = "AllowRoleDecrypt"
      Effect    = "Allow"
      Principal = { AWS = var.kms_decrypt_role_arn }
      Action    = ["kms:Decrypt"]
      Resource  = "*"
    }]
    : []
  )

  tags = {
    Name      = "${var.name}-cloudtrail"
    ManagedBy = "Terraform"
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail logs and the CloudWatch Log Group."
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat([
      {
        Sid    = "AllowRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailEncrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
          }
        }
      },
      {
        Sid    = "AllowS3BucketEncryption"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${local.region}.amazonaws.com"
          }
        }
      }
    ], local.kms_optional_statements)
  })

  tags = local.tags
}

resource "aws_kms_alias" "cloudtrail" {
  name          = var.kms_key_alias_prefix
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.effective_bucket_name
  force_destroy = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = var.enable_bucket_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn"     = local.cloudtrail_arn
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"      = "bucket-owner-full-control"
            "aws:SourceArn"     = local.cloudtrail_arn
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "DenyInsecureTransport"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "${var.name}-cloudtrail"
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  tags = local.tags
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "${var.name}-cloudtrail-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "aws:SourceArn" = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "${var.name}-cloudtrail-cloudwatch"
  role = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name = "${var.name}-cloudtrail"

  tags = local.tags
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  arn = aws_sns_topic.cloudtrail[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.cloudtrail[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceArn"     = local.cloudtrail_arn
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  enable_log_file_validation    = var.enable_log_file_validation
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = var.create_sns_topic ? local.sns_topic_name : null

  event_selector {
    read_write_type           = var.event_selector_read_write_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resource_selectors
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value
    }
  }

  tags = local.tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_s3_bucket_versioning.cloudtrail_logs,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail_logs,
    aws_sns_topic_policy.cloudtrail,
  ]
}

output "cloudtrail_id" {
  description = "ID of the CloudTrail trail."
  value       = aws_cloudtrail.main.id
}

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.main.arn
}

output "cloudtrail_s3_bucket_name" {
  description = "Name of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "cloudtrail_s3_bucket_arn" {
  description = "ARN of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group receiving CloudTrail logs."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch Log Group receiving CloudTrail logs."
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_key_alias" {
  description = "Alias of the KMS key used for CloudTrail encryption."
  value       = aws_kms_alias.cloudtrail.name
}

output "sns_topic_arn" {
  description = "Effective SNS topic ARN for CloudTrail notifications (empty if neither created nor supplied)."
  value       = local.effective_sns_topic_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = "legion"
}

data "aws_iam_policy" "eks_cluster" {
  name = "AmazonEKSClusterPolicy"
}

data "aws_iam_policy" "eks_service" {
  name = "AmazonEKSServicePolicy"
}

data "aws_iam_policy" "eks_worker_node" {
  name = "AmazonEKSWorkerNodePolicy"
}

data "aws_iam_policy" "eks_cni" {
  name = "AmazonEKS_CNI_Policy"
}

data "aws_iam_policy" "ecr_read_only" {
  name = "AmazonEC2ContainerRegistryReadOnly"
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    sid     = "EKSAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster" {
  role       = aws_iam_role.eks_master.name
  policy_arn = data.aws_iam_policy.eks_cluster.arn
}

resource "aws_iam_role_policy_attachment" "eks_master_service" {
  role       = aws_iam_role.eks_master.name
  policy_arn = data.aws_iam_policy.eks_service.arn
}

resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_node_worker" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.eks_worker_node.arn
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.eks_cni.arn
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.ecr_read_only.arn
}

data "aws_iam_policy_document" "cluster_autoscaler" {
  statement {
    sid     = "ClusterAutoscalerReadOnly"
    effect  = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  statement {
    sid     = "ClusterAutoscalerCapacityModification"
    effect  = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["arn:aws:autoscaling:*:*:autoScalingGroup:*:autoScalingGroupName/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "cluster_autoscaler" {
  name   = "eks-worker-autoscaling-${var.cluster_name}"
  policy = data.aws_iam_policy_document.cluster_autoscaler.json
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.cluster_autoscaler.arn
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Static provider metadata lookups (no pre-existing infrastructure required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Inputs (non-infrastructure metadata only, with defaults so apply is unattended)
###############################################################################

variable "project" {
  description = "Project identifier applied to every taggable resource."
  type        = string
  default     = "iam-access-management"
}

variable "environment" {
  description = "Environment identifier applied to every taggable resource."
  type        = string
  default     = "prod"
}

###############################################################################
# Locals: account metadata, tags and scoped ARN patterns
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  # Name prefix used to scope artifact/state buckets and objects without
  # hardcoding any account-specific resource identifier.
  s3_bucket_name_prefix = "iam-workload-"

  # ARN patterns are constructed from provider metadata + the declared prefix,
  # never from pre-existing resources looked up via data sources.
  acm_certificate_arn         = "arn:${local.partition}:acm:${local.region}:${local.account_id}:certificate/*"
  cloudfront_distribution_arn = "arn:${local.partition}:cloudfront::${local.account_id}:distribution/*"
  iam_role_arn                = "arn:${local.partition}:iam::${local.account_id}:role/*"
  iam_policy_arn              = "arn:${local.partition}:iam::${local.account_id}:policy/*"
  lambda_function_arn         = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
  logs_log_group_arn          = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
  route53_hosted_zone_arn     = "arn:${local.partition}:route53:::hostedzone/*"
  s3_bucket_arn               = "arn:${local.partition}:s3:::${local.s3_bucket_name_prefix}*"
  s3_object_arn               = "arn:${local.partition}:s3:::${local.s3_bucket_name_prefix}*/*"
  sqs_queue_arn               = "arn:${local.partition}:sqs:${local.region}:${local.account_id}:*"
}

###############################################################################
# Permission sets
###############################################################################

# Deliberate, explicitly justified full-administrative wildcard. The "admin"
# and "admin-terraform-cloud" workloads are required to hold unrestricted
# account administration, so Action "*" combined with Resource "*" is
# intentional and confined to this single document.
data "aws_iam_policy_document" "admin_full_access" {
  statement {
    sid       = "FullAdministrativeAccess"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

# Single source of truth for the serverless permission set. It is referenced by
# both the inline group policy and the customer managed policy so the two are
# guaranteed to be identical.
data "aws_iam_policy_document" "serverless" {
  statement {
    sid    = "AcmCertificateManagement"
    effect = "Allow"
    actions = [
      "acm:RequestCertificate",
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:DeleteCertificate",
      "acm:AddTagsToCertificate",
      "acm:RemoveTagsFromCertificate",
      "acm:ListTagsForCertificate",
    ]
    resources = [local.acm_certificate_arn]
  }

  statement {
    sid    = "CloudFrontDistributionManagement"
    effect = "Allow"
    actions = [
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:UpdateDistribution",
      "cloudfront:DeleteDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:CreateInvalidation",
      "cloudfront:GetInvalidation",
      "cloudfront:TagResource",
      "cloudfront:UntagResource",
      "cloudfront:ListTagsForResource",
    ]
    resources = [local.cloudfront_distribution_arn]
  }

  statement {
    sid    = "IamRoleManagement"
    effect = "Allow"
    actions = [
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:GetRole",
      "iam:PassRole",
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy",
      "iam:PutRolePolicy",
      "iam:DeleteRolePolicy",
      "iam:GetRolePolicy",
      "iam:ListRolePolicies",
      "iam:ListAttachedRolePolicies",
      "iam:TagRole",
      "iam:UntagRole",
    ]
    resources = [local.iam_role_arn]
  }

  statement {
    sid    = "LambdaFunctionManagement"
    effect = "Allow"
    actions = [
      "lambda:CreateFunction",
      "lambda:DeleteFunction",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "lambda:InvokeFunction",
      "lambda:PublishVersion",
      "lambda:AddPermission",
      "lambda:RemovePermission",
      "lambda:ListVersionsByFunction",
      "lambda:ListTags",
      "lambda:TagResource",
      "lambda:UntagResource",
    ]
    resources = [local.lambda_function_arn]
  }

  statement {
    sid    = "CloudWatchLogsManagement"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:DeleteLogGroup",
      "logs:PutRetentionPolicy",
      "logs:TagLogGroup",
      "logs:UntagLogGroup",
    ]
    resources = [local.logs_log_group_arn]
  }

  statement {
    sid    = "Route53RecordManagement"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:GetChange",
      "route53:ListResourceRecordSets",
      "route53:ListHostedZones",
      "route53:ListHostedZonesByName",
      "route53:GetHostedZone",
    ]
    resources = [local.route53_hosted_zone_arn]
  }

  statement {
    sid    = "S3ArtifactManagement"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketPolicy",
      "s3:PutBucketPolicy",
      "s3:PutBucketTagging",
      "s3:GetBucketTagging",
    ]
    resources = [
      local.s3_bucket_arn,
      local.s3_object_arn,
    ]
  }

  statement {
    sid    = "SqsQueueManagement"
    effect = "Allow"
    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:SetQueueAttributes",
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [local.sqs_queue_arn]
  }
}

# Targeted CI/CD permission set for the "github" group.
data "aws_iam_policy_document" "github" {
  statement {
    sid    = "AcmCertificateLifecycle"
    effect = "Allow"
    actions = [
      "acm:RequestCertificate",
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:ListTagsForCertificate",
    ]
    resources = [local.acm_certificate_arn]
  }

  statement {
    sid    = "CloudFrontDeployment"
    effect = "Allow"
    actions = [
      "cloudfront:CreateDistribution",
      "cloudfront:UpdateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:CreateInvalidation",
      "cloudfront:GetInvalidation",
    ]
    resources = [local.cloudfront_distribution_arn]
  }

  statement {
    sid    = "IamDeploymentSupport"
    effect = "Allow"
    actions = [
      "iam:GetRole",
      "iam:PassRole",
      "iam:ListRolePolicies",
      "iam:GetRolePolicy",
    ]
    resources = [local.iam_role_arn]
  }

  statement {
    sid    = "LambdaDeployment"
    effect = "Allow"
    actions = [
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "lambda:PublishVersion",
      "lambda:ListVersionsByFunction",
    ]
    resources = [local.lambda_function_arn]
  }

  statement {
    sid    = "Route53RecordUpdates"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:GetChange",
      "route53:ListResourceRecordSets",
    ]
    resources = [local.route53_hosted_zone_arn]
  }

  statement {
    sid    = "S3ArtifactPublishing"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [
      local.s3_bucket_arn,
      local.s3_object_arn,
    ]
  }

  statement {
    sid    = "SqsEventDelivery"
    effect = "Allow"
    actions = [
      "sqs:SendMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
    ]
    resources = [local.sqs_queue_arn]
  }
}

# Trust policy allowing Lambda and Edge Lambda to assume the serverless role.
data "aws_iam_policy_document" "serverless_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "lambda.amazonaws.com",
        "edgelambda.amazonaws.com",
      ]
    }
  }
}

###############################################################################
# IAM groups
###############################################################################

resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

###############################################################################
# Inline group policies
###############################################################################

# Justified wildcard: the "admin" group is intentionally granted full
# administrative access as required by the admin workload.
resource "aws_iam_group_policy" "admin" {
  name   = "admin-full-access"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_full_access.json
}

# Justified wildcard: the "admin-terraform-cloud" group is intentionally
# granted full administrative access as required by the Terraform Cloud
# administration workload.
resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-full-access"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_full_access.json
}

resource "aws_iam_group_policy" "github" {
  name   = "github-cicd"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

# Same single document as the customer managed serverless policy below.
resource "aws_iam_group_policy" "serverless" {
  name   = "serverless"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless.json
}

###############################################################################
# IAM users
###############################################################################

resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
  tags = local.tags
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
  tags = local.tags
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
  tags = local.tags
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
  tags = local.tags
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
  tags = local.tags
}

###############################################################################
# Group memberships
###############################################################################

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_macbook_pro" {
  user   = aws_iam_user.admin_macbook_pro.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud" {
  user   = aws_iam_user.admin_terraform_cloud.name
  groups = [aws_iam_group.admin_terraform_cloud.name]
}

resource "aws_iam_user_group_membership" "github" {
  user   = aws_iam_user.github.name
  groups = [aws_iam_group.github.name]
}

resource "aws_iam_user_group_membership" "serverless" {
  user   = aws_iam_user.serverless.name
  groups = [aws_iam_group.serverless.name]
}

###############################################################################
# Programmatic credentials (values only exist in state / Secrets Manager)
###############################################################################

resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

resource "aws_secretsmanager_secret" "admin_macbook_pro_access_key" {
  name        = "iam/admin-macbook-pro/access-key"
  description = "Access key credentials for the admin-macbook-pro IAM user."
  tags        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_macbook_pro_access_key" {
  secret_id = aws_secretsmanager_secret.admin_macbook_pro_access_key.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_macbook_pro.id
    secret_access_key = aws_iam_access_key.admin_macbook_pro.secret
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "admin_terraform_cloud_access_key" {
  name        = "iam/admin-terraform-cloud/access-key"
  description = "Access key credentials for the admin-terraform-cloud IAM user."
  tags        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_terraform_cloud_access_key" {
  secret_id = aws_secretsmanager_secret.admin_terraform_cloud_access_key.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_terraform_cloud.id
    secret_access_key = aws_iam_access_key.admin_terraform_cloud.secret
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Serverless role + customer managed policy (identical permission set)
###############################################################################

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.serverless_assume_role.json
  tags               = local.tags
}

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Permissions for the serverless Lambda/Edge Lambda execution role."
  policy      = data.aws_iam_policy_document.serverless.json
  tags        = local.tags
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

###############################################################################
# Outputs
###############################################################################

output "group_names" {
  description = "Names of the managed IAM groups."
  value = {
    admin                 = aws_iam_group.admin.name
    admin_terraform_cloud = aws_iam_group.admin_terraform_cloud.name
    github                = aws_iam_group.github.name
    serverless            = aws_iam_group.serverless.name
  }
}

output "group_arns" {
  description = "ARNs of the managed IAM groups."
  value = {
    admin                 = aws_iam_group.admin.arn
    admin_terraform_cloud = aws_iam_group.admin_terraform_cloud.arn
    github                = aws_iam_group.github.arn
    serverless            = aws_iam_group.serverless.arn
  }
}

output "user_names" {
  description = "Names of the managed IAM users."
  value = {
    admin                 = aws_iam_user.admin.name
    admin_macbook_pro     = aws_iam_user.admin_macbook_pro.name
    admin_terraform_cloud = aws_iam_user.admin_terraform_cloud.name
    github                = aws_iam_user.github.name
    serverless            = aws_iam_user.serverless.name
  }
}

output "user_arns" {
  description = "ARNs of the managed IAM users."
  value = {
    admin                 = aws_iam_user.admin.arn
    admin_macbook_pro     = aws_iam_user.admin_macbook_pro.arn
    admin_terraform_cloud = aws_iam_user.admin_terraform_cloud.arn
    github                = aws_iam_user.github.arn
    serverless            = aws_iam_user.serverless.arn
  }
}

output "serverless_role_arn" {
  description = "ARN of the serverless IAM role."
  value       = aws_iam_role.serverless.arn
}

output "serverless_managed_policy_arn" {
  description = "ARN of the customer managed serverless IAM policy."
  value       = aws_iam_policy.serverless.arn
}

output "access_key_ids" {
  description = "Access key IDs issued for the two admin users."
  sensitive   = true
  value = {
    admin_macbook_pro     = aws_iam_access_key.admin_macbook_pro.id
    admin_terraform_cloud = aws_iam_access_key.admin_terraform_cloud.id
  }
}

output "access_key_secrets" {
  description = "Secret access keys issued for the two admin users."
  sensitive   = true
  value = {
    admin_macbook_pro     = aws_iam_access_key.admin_macbook_pro.secret
    admin_terraform_cloud = aws_iam_access_key.admin_terraform_cloud.secret
  }
}

output "access_key_secret_arns" {
  description = "Secrets Manager ARNs holding the generated access key credentials."
  value = {
    admin_macbook_pro     = aws_secretsmanager_secret.admin_macbook_pro_access_key.arn
    admin_terraform_cloud = aws_secretsmanager_secret.admin_terraform_cloud_access_key.arn
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "namespace" {
  description = "Namespace (organization) used for CloudPosse standardized naming."
  type        = string
  default     = "acme"
}

variable "environment" {
  description = "Environment used for CloudPosse standardized naming."
  type        = string
  default     = "ue1"
}

variable "name" {
  description = "Base name used for CloudPosse standardized naming."
  type        = string
  default     = "iam"
}

variable "tags" {
  description = "Additional tags applied to all managed resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

variable "attributes" {
  description = "Additional attributes used for CloudPosse standardized naming."
  type        = list(string)
  default     = []
}

variable "admin_users" {
  description = "List of IAM user names to create and add to the admin group."
  type        = list(string)
  default     = ["admin-user"]
}

variable "non_admin_users" {
  description = "List of IAM user names to create and add to the non-admin group."
  type        = list(string)
  default     = ["developer-user"]
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  iam_arn_prefix = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}"
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  administrator_access_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  stage       = "admin"
  name        = var.name
  attributes  = concat(var.attributes, ["admin"])
  tags        = var.tags
  delimiter   = "-"
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  stage       = "nonadmin"
  name        = var.name
  attributes  = concat(var.attributes, ["nonadmin"])
  tags        = var.tags
  delimiter   = "-"
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowManageOwnCredentials"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "${local.iam_arn_prefix}:user/$${aws:username}",
      "${local.iam_arn_prefix}:mfa/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowAccountLevelReadOnly"
    effect = "Allow"

    actions = [
      "iam:ListUsers",
      "iam:GetAccountPasswordPolicy",
      "iam:ListMFADevices",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowDeactivateOwnMFADevicesOnlyWithMFA"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "${local.iam_arn_prefix}:user/$${aws:username}",
      "${local.iam_arn_prefix}:mfa/$${aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.admin_label.id}-self-management"
  description = "Allow users to manage their own credentials and virtual MFA devices; MFA is required to deactivate or delete MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.admin_label.tags
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"

    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin_role.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.admin_label.id}-assume-admin-role"
  description = "Allow members of the admin group to assume the dedicated admin role, but only with an active MFA session."
  policy      = data.aws_iam_policy_document.admin_assume_role.json
  tags        = module.admin_label.tags
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowAccountRootAssumeAdminRoleWithMFA"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin_role" {
  name               = module.admin_label.id
  description        = "Dedicated administrative role that can only be assumed with MFA."
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  tags               = module.admin_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin_role.name
  policy_arn = local.administrator_access_policy_arn
}

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = "/"
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)

  name = each.value
  path = "/"
  tags = module.admin_label.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)

  name = each.value
  path = "/"
  tags = module.non_admin_label.tags
}

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0

  name  = "${module.admin_label.id}-membership"
  group = aws_iam_group.admin.name
  users = [for u in aws_iam_user.admin : u.name]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0

  name  = "${module.non_admin_label.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for u in aws_iam_user.non_admin : u.name]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Master toggles and target selection
###############################################################################

variable "create" {
  description = "Master toggle. When false, no resources are provisioned by this module."
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "When true a new security group is created. When false, rules are attached to the security group supplied via existing_security_group_id."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to. Required when create_security_group = false."
  type        = string
  default     = ""

  validation {
    condition     = var.create_security_group || length(var.existing_security_group_id) > 0
    error_message = "existing_security_group_id must be a non-empty security group ID when create_security_group is set to false."
  }
}

variable "vpc_id" {
  description = "VPC ID that hosts the new security group. When empty and create_security_group = true, a fallback VPC (10.0.0.0/16) is created."
  type        = string
  default     = ""
}

variable "security_group_description" {
  description = "Description applied to the managed security group."
  type        = string
  default     = "Managed by Terraform - network access controls for application workloads"
}

###############################################################################
# Label module inputs (user controlled only)
###############################################################################

variable "name" {
  description = "Name used by the label module to build resource identifiers."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment label (e.g. dev, staging, prod)."
  type        = string
  default     = ""
}

variable "delimiter" {
  description = "Delimiter used by the label module between labels."
  type        = string
  default     = "-"
}

variable "label_order" {
  description = "Order in which the label module composes the resource id."
  type        = list(string)
  default     = ["environment", "name"]
}

variable "tags" {
  description = "Additional tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Managed prefix list inputs
###############################################################################

variable "create_prefix_list" {
  description = "Toggle managed prefix list creation. Only effective when prefix_list_ids is empty."
  type        = bool
  default     = true
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list IDs to use. When non-empty the module will not create a prefix list."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for id in var.prefix_list_ids : length(id) > 0])
    error_message = "Every supplied prefix_list_ids entry must be a non-empty managed prefix list ID."
  }
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list. At most 5 IPv4 CIDRs are allowed (max_entries = 5)."
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []

  validation {
    condition     = length(var.prefix_list_entries) <= 5
    error_message = "A managed prefix list created by this module supports a maximum of 5 entries."
  }

  validation {
    condition     = alltrue([for e in var.prefix_list_entries : can(cidrhost(e.cidr, 0))])
    error_message = "Every prefix_list_entries.cidr value must be a valid IPv4 CIDR block."
  }
}

###############################################################################
# Ingress rule inputs
###############################################################################

variable "ingress_cidr_blocks" {
  description = "Ingress rules keyed by name, sourced from CIDR blocks. Contains no world-open defaults; opening 0.0.0.0/0 or ::/0 on ports other than 80/443 requires explicit justification."
  type = map(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = list(string)
    ipv6_cidr_blocks = list(string)
    description      = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.ingress_cidr_blocks :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each ingress_cidr_blocks entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }

  validation {
    condition = alltrue(flatten([
      for k, v in var.ingress_cidr_blocks : [
        for c in concat(v.cidr_blocks, v.ipv6_cidr_blocks) : can(cidrhost(c, 0))
      ]
    ]))
    error_message = "Each ingress_cidr_blocks entry must contain only valid CIDR blocks."
  }
}

variable "ingress_self" {
  description = "Self-referencing ingress rules keyed by name. Empty by default for least privilege."
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.ingress_self :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each ingress_self entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }
}

variable "ingress_source_security_group_ids" {
  description = "Ingress rules keyed by name, sourced from another security group ID. Empty by default for least privilege."
  type = map(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.ingress_source_security_group_ids :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol) &&
      length(v.source_security_group_id) > 0
    ])
    error_message = "Each ingress_source_security_group_ids entry must use ports between 0 and 65535, protocol tcp, udp, icmp, icmpv6 or -1, and a non-empty source_security_group_id."
  }
}

variable "ingress_prefix_list_ids" {
  description = "Ingress rules keyed by name, sourced from managed prefix lists. When prefix_list_ids is empty the module-managed prefix list is used. Empty by default for least privilege."
  type = map(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = list(string)
    description     = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.ingress_prefix_list_ids :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each ingress_prefix_list_ids entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }
}

###############################################################################
# Egress rule inputs
###############################################################################

variable "egress_cidr_blocks" {
  description = "Egress rules keyed by name, targeting CIDR blocks. Empty by default so no egress traffic is opened implicitly."
  type = map(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = list(string)
    ipv6_cidr_blocks = list(string)
    description      = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.egress_cidr_blocks :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each egress_cidr_blocks entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }

  validation {
    condition = alltrue(flatten([
      for k, v in var.egress_cidr_blocks : [
        for c in concat(v.cidr_blocks, v.ipv6_cidr_blocks) : can(cidrhost(c, 0))
      ]
    ]))
    error_message = "Each egress_cidr_blocks entry must contain only valid CIDR blocks."
  }
}

variable "egress_self" {
  description = "Self-referencing egress rules keyed by name. Empty by default so no egress traffic is opened implicitly."
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.egress_self :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each egress_self entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }
}

variable "egress_source_security_group_ids" {
  description = "Egress rules keyed by name, targeting another security group ID. Empty by default so no egress traffic is opened implicitly."
  type = map(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.egress_source_security_group_ids :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol) &&
      length(v.source_security_group_id) > 0
    ])
    error_message = "Each egress_source_security_group_ids entry must use ports between 0 and 65535, protocol tcp, udp, icmp, icmpv6 or -1, and a non-empty source_security_group_id."
  }
}

variable "egress_prefix_list_ids" {
  description = "Egress rules keyed by name, targeting managed prefix lists. When prefix_list_ids is empty the module-managed prefix list is used. Empty by default so no egress traffic is opened implicitly."
  type = map(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = list(string)
    description     = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.egress_prefix_list_ids :
      v.from_port >= 0 && v.from_port <= 65535 &&
      v.to_port >= 0 && v.to_port <= 65535 &&
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], v.protocol)
    ])
    error_message = "Each egress_prefix_list_ids entry must use ports between 0 and 65535 and protocol tcp, udp, icmp, icmpv6 or -1."
  }
}

###############################################################################
# Labels
###############################################################################

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  delimiter   = var.delimiter
  label_order = var.label_order
}

###############################################################################
# Locals
###############################################################################

locals {
  create_security_group = var.create && var.create_security_group
  create_fallback_vpc   = var.create && var.create_security_group && length(var.vpc_id) == 0
  create_prefix_list    = var.create && var.create_prefix_list && length(var.prefix_list_ids) == 0

  effective_vpc_id = length(var.vpc_id) > 0 ? var.vpc_id : try(aws_vpc.main[0].id, null)

  security_group_id = var.create ? (
    var.create_security_group ? try(aws_security_group.this[0].id, null) : var.existing_security_group_id
  ) : null

  prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : try(
    [aws_ec2_managed_prefix_list.this[0].id], []
  )

  merged_tags = merge(module.labels.tags, var.tags)
}

###############################################################################
# Fallback VPC (only when a new security group is requested without a VPC ID)
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.merged_tags, {
    Name = "${module.labels.id}-vpc"
  })
}

###############################################################################
# Security group (new) - no inline ingress/egress blocks
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_security_group ? 1 : 0

  name        = "${module.labels.id}-sg"
  description = var.security_group_description
  vpc_id      = local.effective_vpc_id

  tags = local.merged_tags
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = "${module.labels.id}-prefix-list"
  address_family = "IPv4"
  max_entries    = 5

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = local.merged_tags
}

###############################################################################
# Ingress rules (standalone resources)
###############################################################################

resource "aws_security_group_rule" "ingress_cidr_blocks" {
  for_each = { for k, v in var.ingress_cidr_blocks : k => v if var.create }

  type              = "ingress"
  security_group_id = local.security_group_id

  from_port        = each.value.from_port
  to_port          = each.value.to_port
  protocol         = each.value.protocol
  cidr_blocks      = each.value.cidr_blocks
  ipv6_cidr_blocks = each.value.ipv6_cidr_blocks
  description      = each.value.description
}

resource "aws_security_group_rule" "ingress_self" {
  for_each = { for k, v in var.ingress_self : k => v if var.create }

  type              = "ingress"
  security_group_id = local.security_group_id

  from_port   = each.value.from_port
  to_port     = each.value.to_port
  protocol    = each.value.protocol
  self        = true
  description = each.value.description
}

resource "aws_security_group_rule" "ingress_source_security_group_ids" {
  for_each = { for k, v in var.ingress_source_security_group_ids : k => v if var.create }

  type              = "ingress"
  security_group_id = local.security_group_id

  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = each.value.description
}

resource "aws_security_group_rule" "ingress_prefix_list_ids" {
  for_each = { for k, v in var.ingress_prefix_list_ids : k => v if var.create }

  type              = "ingress"
  security_group_id = local.security_group_id

  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  prefix_list_ids = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : local.prefix_list_ids
  description     = each.value.description
}

###############################################################################
# Egress rules (standalone resources)
###############################################################################

resource "aws_security_group_rule" "egress_cidr_blocks" {
  for_each = { for k, v in var.egress_cidr_blocks : k => v if var.create }

  type              = "egress"
  security_group_id = local.security_group_id

  from_port        = each.value.from_port
  to_port          = each.value.to_port
  protocol         = each.value.protocol
  cidr_blocks      = each.value.cidr_blocks
  ipv6_cidr_blocks = each.value.ipv6_cidr_blocks
  description      = each.value.description
}

resource "aws_security_group_rule" "egress_self" {
  for_each = { for k, v in var.egress_self : k => v if var.create }

  type              = "egress"
  security_group_id = local.security_group_id

  from_port   = each.value.from_port
  to_port     = each.value.to_port
  protocol    = each.value.protocol
  self        = true
  description = each.value.description
}

resource "aws_security_group_rule" "egress_source_security_group_ids" {
  for_each = { for k, v in var.egress_source_security_group_ids : k => v if var.create }

  type              = "egress"
  security_group_id = local.security_group_id

  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = each.value.description
}

resource "aws_security_group_rule" "egress_prefix_list_ids" {
  for_each = { for k, v in var.egress_prefix_list_ids : k => v if var.create }

  type              = "egress"
  security_group_id = local.security_group_id

  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  prefix_list_ids = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : local.prefix_list_ids
  description     = each.value.description
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the managed security group (newly created or the supplied existing group)."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group. Null when attaching rules to an existing security group."
  value       = local.create_security_group ? try(aws_security_group.this[0].arn, null) : null
}

output "security_group_name" {
  description = "Name of the newly created security group. Null when attaching rules to an existing security group."
  value       = local.create_security_group ? try(aws_security_group.this[0].name, null) : null
}

output "effective_vpc_id" {
  description = "VPC that hosts the security group: the fallback VPC or the user supplied vpc_id."
  value       = local.effective_vpc_id
}

output "managed_prefix_list_id" {
  description = "ID of the managed prefix list created by this module."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "managed_prefix_list_arn" {
  description = "ARN of the managed prefix list created by this module."
  value       = try(aws_ec2_managed_prefix_list.this[0].arn, null)
}

output "tags" {
  description = "Merged tags applied to every taggable resource in this module."
  value       = local.merged_tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.11"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  cluster_name    = "demo-eks"
  region          = "us-east-1"
  cluster_version = "1.31"
  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
}

###############################################################################
# Networking: VPC, subnets, gateways, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = local.cluster_name
    Environment = "demo"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = {
    Name                                          = "${local.cluster_name}-public"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    "kubernetes.io/role/elb"                      = "1"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = {
    Name                                          = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    "kubernetes.io/role/internal-elb"             = "1"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.cluster_name}-nat"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-public"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-private"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# IAM: EKS cluster role
###############################################################################

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "eksClusterRole"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = {
    Name = "eksClusterRole"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

###############################################################################
# KMS key for EKS secrets encryption
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "KMS key for ${local.cluster_name} secrets encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEKSClusterUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster.arn
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-eks"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${local.cluster_name}-eks"
  target_key_id = aws_kms_key.eks.key_id
}

data "aws_iam_policy_document" "eks_cluster_kms" {
  statement {
    effect = "Allow"

    actions = [
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:Encrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]

    resources = [aws_kms_key.eks.arn]
  }
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name   = "eks-cluster-kms"
  role   = aws_iam_role.eks_cluster.id
  policy = data.aws_iam_policy_document.eks_cluster_kms.json
}

###############################################################################
# EKS control plane
###############################################################################

resource "aws_eks_cluster" "demo_eks" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  version                       = local.cluster_version
  bootstrap_self_managed_addons = false

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = {
    Name = local.cluster_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms,
  ]
}

###############################################################################
# TLS key pair for worker nodes
###############################################################################

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

###############################################################################
# Worker node security group
###############################################################################

resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node"
  description = "Security group for ${local.cluster_name} worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name                                          = "${local.cluster_name}-node"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "node_self_ingress" {
  type              = "ingress"
  from_port         = 0
  to_port           = 65535
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node.id
  description       = "Allow unrestricted node-to-node communication"
}

resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.node.id
  description       = "Allow outbound traffic within the VPC CIDR"
}

resource "aws_security_group_rule" "node_ingress_control_plane_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow HTTPS from EKS control plane"
}

resource "aws_security_group_rule" "node_ingress_control_plane_ephemeral" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow control plane to node kubelet communication"
}

resource "aws_security_group_rule" "node_egress_control_plane_443" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow HTTPS to EKS control plane"
}

resource "aws_security_group_rule" "node_egress_control_plane_ephemeral" {
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow node to control plane communication"
}

###############################################################################
# IAM: worker node role and instance profile
###############################################################################

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "eks-demo-node"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = {
    Name = "eks-demo-node"
  }
}

resource "aws_iam_role_policy_attachment" "eks_node_worker" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_ssm" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-demo-node"
  role = aws_iam_role.eks_node.name
}

###############################################################################
# EKS-optimized Amazon Linux 2 AMI (via SSM)
###############################################################################

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.29/amazon-linux-2/recommended/image_id"
}

###############################################################################
# Worker node launch template
###############################################################################

resource "aws_launch_template" "eks_node" {
  name          = "${local.cluster_name}-node-lt"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  vpc_security_group_ids = [aws_security_group.node.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node.name
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o pipefail

    /etc/eks/bootstrap.sh ${local.cluster_name}

    /opt/aws/bin/cfn-signal --success true \
      --stack eks-cluster-stack \
      --resource NodeGroup \
      --region ${local.region}
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name                                          = "${local.cluster_name}-node"
      "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name = "${local.cluster_name}-node"
    }
  }

  tags = {
    Name = "${local.cluster_name}-node-lt"
  }
}

resource "time_sleep" "launch_template_settle" {
  depends_on = [aws_launch_template.eks_node]

  create_duration = "30s"
}

###############################################################################
# CloudFormation-managed Auto Scaling Group for worker nodes
###############################################################################

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name               = "eks-cluster-stack"
  capabilities       = ["CAPABILITY_NAMED_IAM"]
  timeout_in_minutes = 10

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "Auto Scaling Group for ${local.cluster_name} worker nodes"

    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"

        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }

        Properties = {
          MinSize         = "1"
          DesiredCapacity = "3"
          MaxSize         = "4"

          HealthCheckType        = "EC2"
          HealthCheckGracePeriod = 300

          VPCZoneIdentifier = aws_subnet.private[*].id

          LaunchTemplate = {
            LaunchTemplateId = aws_launch_template.eks_node.id
            Version          = aws_launch_template.eks_node.latest_version
          }
        }
      }
    }

    Outputs = {
      AsgId = {
        Value = { Ref = "NodeGroup" }
      }
    }
  })

  tags = {
    Name                                          = "eks-cluster-stack"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }

  depends_on = [time_sleep.launch_template_settle]
}

###############################################################################
# Outputs
###############################################################################

output "node_instance_role_arn" {
  description = "ARN of the EKS worker node instance role"
  value       = aws_iam_role.eks_node.arn
}

output "node_security_group_id" {
  description = "ID of the EKS worker node security group"
  value       = aws_security_group.node.id
}

output "autoscaling_group_id" {
  description = "ID of the Auto Scaling Group created by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["AsgId"]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# Only the disaster-recovery alias is declared here. The default provider is
# injected and managed by the deployment harness.
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

variable "primary_region" {
  description = "Primary AWS region hosting the live Terraform state bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Disaster-recovery AWS region for cross-region state replication."
  type        = string
  default     = "us-west-2"
}

variable "stacks" {
  description = "Map of EKS stacks requiring isolated state locking and scoped access."
  type = map(object({
    name   = string
    region = string
    prefix = string
  }))
  default = {
    alpha = {
      name   = "alpha"
      region = "us-east-1"
      prefix = "eks/alpha"
    }
    beta = {
      name   = "beta"
      region = "us-west-2"
      prefix = "eks/beta"
    }
  }
}

variable "tags" {
  description = "Standardized state-management labels applied to every taggable resource."
  type        = map(string)
  default = {
    Project     = "eks-stacks"
    Environment = "shared"
    ManagedBy   = "terraform"
    Purpose     = "terraform-remote-state"
    Compliance  = "state-management"
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id       = data.aws_caller_identity.current.account_id
  account_root_arn = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = merge(
    {
      ManagedBy = "terraform"
      Purpose   = "terraform-remote-state"
    },
    var.tags
  )

  primary_bucket_name = "eks-tfstate-${local.account_id}-${var.primary_region}"
  replica_bucket_name = "eks-tfstate-${local.account_id}-${var.replica_region}"
}

###############################################################################
# Primary KMS key (us-east-1) - default SSE-KMS for all primary state objects
###############################################################################

data "aws_iam_policy_document" "state_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleKeyUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "state" {
  description             = "SSE-KMS key for the primary Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/eks-tfstate-primary"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_kms_key_policy" "state" {
  key_id = aws_kms_key.state.id
  policy = data.aws_iam_policy_document.state_kms.json
}

###############################################################################
# Replica KMS key (DR region) - dedicated key, never reused from primary
###############################################################################

data "aws_iam_policy_document" "replica_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleKeyUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "SSE-KMS key for the replica Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/eks-tfstate-replica"
  target_key_id = aws_kms_key.replica.key_id
}

resource "aws_kms_key_policy" "replica" {
  provider = aws.replica
  key_id   = aws_kms_key.replica.id
  policy   = data.aws_iam_policy_document.replica_kms.json
}

###############################################################################
# Primary S3 state bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.primary_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyNonKMSUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.state]
}

###############################################################################
# Replica S3 state bucket (DR region)
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyNonKMSUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.replica.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

###############################################################################
# Cross-region replication IAM role and least-privilege policy
###############################################################################

resource "aws_iam_role" "replication" {
  name = "eks-tfstate-replication-role"
  tags = local.common_tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.state.arn]
  }

  statement {
    sid    = "SourceObjectReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.state.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectWritePermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.state.arn]
  }

  statement {
    sid    = "EncryptDestinationObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name   = "eks-tfstate-replication-policy"
  policy = data.aws_iam_policy_document.replication.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# S3 cross-region replication configuration (all prefixes, KMS re-encrypted)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "state-cross-region-replication"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Per-stack DynamoDB lock tables
###############################################################################

resource "aws_dynamodb_table" "lock" {
  for_each = var.stacks

  name         = "eks-tfstate-lock-${each.value.name}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Per-stack least-privilege IAM policies (table + prefix + KMS scoped)
###############################################################################

data "aws_iam_policy_document" "stack" {
  for_each = var.stacks

  statement {
    sid    = "DynamoDBStateLocking"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:DescribeTable",
      "dynamodb:BatchWriteItem",
    ]

    resources = [aws_dynamodb_table.lock[each.key].arn]
  }

  statement {
    sid    = "StateBucketListPrefix"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.state.arn]

    condition {
      test     = "StringEquals"
      variable = "s3:prefix"

      values = [each.value.prefix]
    }
  }

  statement {
    sid    = "StateObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.state.arn}/${each.value.prefix}/*"]
  }

  statement {
    sid    = "StateKMSAccess"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.state.arn]
  }
}

resource "aws_iam_policy" "stack" {
  for_each = var.stacks

  name   = "eks-tfstate-access-${each.value.name}"
  policy = data.aws_iam_policy_document.stack[each.key].json
  tags   = local.common_tags
}

###############################################################################
# Generated per-stack backend.tf (relative eks-stacks directory)
###############################################################################

resource "local_file" "backend" {
  for_each = var.stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.state.id}"
        key            = "eks/${each.key}/terraform.tfstate"
        region         = "${var.primary_region}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.state.arn}"
        dynamodb_table = "${aws_dynamodb_table.lock[each.key].name}"
      }
    }
  EOT

  file_permission      = "0644"
  directory_permission = "0755"
}

###############################################################################
# Outputs
###############################################################################

output "primary_bucket_name" {
  description = "Name of the primary (us-east-1) Terraform state bucket."
  value       = aws_s3_bucket.state.id
}

output "primary_bucket_arn" {
  description = "ARN of the primary Terraform state bucket."
  value       = aws_s3_bucket.state.arn
}

output "replica_bucket_name" {
  description = "Name of the disaster-recovery Terraform state bucket."
  value       = aws_s3_bucket.replica.id
}

output "replica_bucket_arn" {
  description = "ARN of the disaster-recovery Terraform state bucket."
  value       = aws_s3_bucket.replica.arn
}

output "primary_kms_key_arn" {
  description = "ARN of the primary SSE-KMS key."
  value       = aws_kms_key.state.arn
}

output "replica_kms_key_arn" {
  description = "ARN of the replica SSE-KMS key."
  value       = aws_kms_key.replica.arn
}

output "replication_role_arn" {
  description = "ARN of the S3 cross-region replication IAM role."
  value       = aws_iam_role.replication.arn
}

output "lock_table_names" {
  description = "Map of stack key to its DynamoDB state-locking table name."
  value       = { for k, v in aws_dynamodb_table.lock : k => v.name }
}

output "stack_policy_arns" {
  description = "Map of stack key to its scoped IAM access policy ARN."
  value       = { for k, v in aws_iam_policy.stack : k => v.arn }
}

output "backend_file_paths" {
  description = "Map of stack key to its generated backend.tf path."
  value       = { for k, v in local_file.backend : k => v.filename }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

locals {
  name_prefix    = random_pet.name.id
  log_group_name = "/aws/apigateway/${random_pet.name.id}"
  sqs_path_uri   = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.main.name}"
}

resource "aws_kms_key" "main" {
  description             = "Customer managed key used to encrypt the ${random_pet.name.id} WebSocket message queue"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${random_pet.name.id}-sqs"
  target_key_id = aws_kms_key.main.key_id
}

resource "aws_sqs_queue" "main" {
  name                              = random_pet.name.id
  kms_master_key_id                 = aws_kms_key.main.arn
  kms_data_key_reuse_period_seconds = 300
  message_retention_seconds         = 86400
  visibility_timeout_seconds        = 30

  tags = {
    Name = random_pet.name.id
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "apigw" {
  name        = "${random_pet.name.id}-apigw-role"
  description = "Execution role assumed by API Gateway for WebSocket AWS service integrations and CloudWatch Logs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApiGatewayToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "apigw" {
  name        = "${random_pet.name.id}-apigw-policy"
  description = "Least privilege policy allowing API Gateway to send messages to the ${random_pet.name.id} queue and write access logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SendMessagesToQueue"
        Effect = "Allow"
        Action = [
          "sqs:SendMessage",
          "sqs:GetQueueUrl",
          "sqs:GetQueueAttributes"
        ]
        Resource = aws_sqs_queue.main.arn
      },
      {
        Sid    = "UseQueueEncryptionKey"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.main.arn
      },
      {
        Sid    = "WriteApiGatewayAccessLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.apigw.arn,
          "${aws_cloudwatch_log_group.apigw.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw" {
  role       = aws_iam_role.apigw.name
  policy_arn = aws_iam_policy.apigw.arn
}

resource "aws_sqs_queue_policy" "main" {
  queue_url = aws_sqs_queue.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApiGatewayIntegrationToSendMessages"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.apigw.arn
        }
        Action = [
          "sqs:SendMessage",
          "sqs:GetQueueAttributes"
        ]
        Resource = aws_sqs_queue.main.arn
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "apigw" {
  name              = local.log_group_name
  retention_in_days = 1
}

resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.apigw.arn

  depends_on = [aws_iam_role_policy_attachment.apigw]
}

resource "aws_apigatewayv2_api" "main" {
  name                       = random_pet.name.id
  description                = "WebSocket API that forwards messages directly to the ${random_pet.name.id} SQS queue"
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# ---------------------------------------------------------------------------
# $connect - mock integration returning HTTP 200
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.main.id
  integration_type = "MOCK"

  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route_response" "connect" {
  api_id             = aws_apigatewayv2_api.main.id
  route_id           = aws_apigatewayv2_route.connect.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "/200"
}

# ---------------------------------------------------------------------------
# $default - forwards the raw client message body to SQS
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_integration" "default" {
  api_id               = aws_apigatewayv2_api.main.id
  integration_type     = "AWS"
  integration_subtype  = "SQS-SendMessage"
  integration_method   = "POST"
  integration_uri      = local.sqs_path_uri
  credentials_arn      = aws_iam_role.apigw.arn
  passthrough_behavior = "NEVER"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$input.body"
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.main.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "/200"
}

# ---------------------------------------------------------------------------
# $disconnect - sends a fixed message to the same queue
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id               = aws_apigatewayv2_api.main.id
  integration_type     = "AWS"
  integration_subtype  = "SQS-SendMessage"
  integration_method   = "POST"
  integration_uri      = local.sqs_path_uri
  credentials_arn      = aws_iam_role.apigw.arn
  passthrough_behavior = "NEVER"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client+disconnected"
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_route_response" "disconnect" {
  api_id             = aws_apigatewayv2_api.main.id
  route_id           = aws_apigatewayv2_route.disconnect.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "disconnect" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.disconnect.id
  integration_response_key = "/200"
}

# ---------------------------------------------------------------------------
# Auto-deployed "dev" stage with access logging
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.main.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn

    format = jsonencode({
      requestId    = "$context.requestId"
      ip           = "$context.identity.sourceIp"
      requestTime  = "$context.requestTime"
      eventType    = "$context.eventType"
      routeKey     = "$context.routeKey"
      connectionId = "$context.connectionId"
      status       = "$context.status"
    })
  }

  depends_on = [aws_api_gateway_account.main]
}

output "websocket_endpoint_url" {
  description = "Full WebSocket endpoint URL including the deployed stage name"
  value       = "${aws_apigatewayv2_api.main.api_endpoint}/${aws_apigatewayv2_stage.dev.name}"
}

output "sqs_queue_url" {
  description = "URL of the SQS queue that receives WebSocket messages"
  value       = aws_sqs_queue.main.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "primary_bucket_name" {
  description = "Base name for the primary S3 bucket (suffixed with the AWS account ID)."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name for the secondary S3 bucket (suffixed with the AWS account ID)."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  primary_bucket_name   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${local.account_id}"
}

# ---------------------------------------------------------------------------
# Primary bucket (us-east-1)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "primary" {
  description             = "Customer managed key for the primary S3 bucket ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.primary_bucket_name}"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Secondary bucket (us-west-2) - required region for MRAP control plane
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary

  bucket = local.secondary_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "secondary" {
  provider = aws.secondary

  description             = "Customer managed key for the secondary S3 bucket ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secondary" {
  provider = aws.secondary

  name          = "alias/${local.secondary_bucket_name}"
  target_key_id = aws_kms_key.secondary.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Replication role and least-privilege policy
# ---------------------------------------------------------------------------

resource "aws_iam_role" "s3_replication" {
  name = "s3-cross-region-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least-privilege permissions for S3 cross-region replication between the primary and secondary buckets."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketListAndVersioning"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.primary.arn
        ]
      },
      {
        Sid    = "SourceObjectRead"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersionForReplication"
        ]
        Resource = [
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketListAndVersioning"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketVersioning"
        ]
        Resource = [
          aws_s3_bucket.secondary.arn
        ]
      },
      {
        Sid    = "DestinationObjectReplicate"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = [
          "${aws_s3_bucket.secondary.arn}/*"
        ]
      },
      {
        Sid    = "SourceKMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.primary.arn
        ]
      },
      {
        Sid    = "DestinationKMSEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.secondary.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# ---------------------------------------------------------------------------
# Replication configuration on the primary bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_iam_role_policy_attachment.s3_replication,
  ]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Multi-Region Access Point (managed from us-west-2)
# ---------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point" "main" {
  provider = aws.secondary

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "main" {
  provider = aws.secondary

  details {
    name = aws_s3control_multi_region_access_point.main.details[0].name

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "AllowOwningAccountObjectAccess"
          Effect = "Allow"
          Principal = {
            AWS = local.account_id
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = "arn:${local.partition}:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.main.alias}/object/*"
        }
      ]
    })
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Provider / account metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  dynamodb_table_arns = [
    "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*",
  ]

  dynamodb_backup_arns = [
    "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:backup/*",
  ]

  log_group_arns = [
    "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*",
    "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*:*",
  ]

  common_tags = {
    ManagedBy = "terraform"
    Purpose   = "dynamodb-backup-automation"
  }
}

###############################################################################
# Shared Lambda assume-role trust policy
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid    = "AllowLambdaServiceToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "create_ddb_backup_role" {
  name        = "create_ddb_backup_role"
  description = "Role assumed by Lambda to create DynamoDB backups"

  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(local.common_tags, {
    Name = "create_ddb_backup_role"
  })
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name        = "remove_ddb_backup_role"
  description = "Role assumed by Lambda to list and delete DynamoDB backups"

  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(local.common_tags, {
    Name = "remove_ddb_backup_role"
  })
}

###############################################################################
# Policy documents
###############################################################################

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "CreateAndDescribeDynamoDbBackups"
    effect = "Allow"

    actions = [
      "dynamodb:CreateBackup",
      "dynamodb:DescribeTable",
    ]

    resources = local.dynamodb_table_arns
  }
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    sid    = "ListDynamoDbBackups"
    effect = "Allow"

    actions = [
      "dynamodb:ListBackups",
    ]

    resources = concat(local.dynamodb_table_arns, local.dynamodb_backup_arns)
  }

  statement {
    sid    = "DeleteDynamoDbBackups"
    effect = "Allow"

    actions = [
      "dynamodb:DeleteBackup",
    ]

    resources = local.dynamodb_backup_arns
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "WriteCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = local.log_group_arns
  }
}

###############################################################################
# Customer managed policies
###############################################################################

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creation of DynamoDB backups for tables in this account"
  policy      = data.aws_iam_policy_document.create_ddb_backup.json

  tags = merge(local.common_tags, {
    Name = "create_ddb_backup_policy"
  })
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deletion of DynamoDB backups in this account"
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json

  tags = merge(local.common_tags, {
    Name = "remove_ddb_backup_policy"
  })
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Allows Lambda functions to write logs to CloudWatch Logs"
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = merge(local.common_tags, {
    Name = "lambda_logging"
  })
}

###############################################################################
# Policy attachments
###############################################################################

resource "aws_iam_role_policy_attachment" "create_ddb_backup_policy_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_policy_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_create_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_remove_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

###############################################################################
# Outputs
###############################################################################

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumed by Lambda to create DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role assumed by Lambda to create DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumed by Lambda to remove DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role assumed by Lambda to remove DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name            = "projectvpc"
  public_subnet_name  = "projectvpc-public-subnet"
  private_subnet_name = "projectvpc-private-subnet"
  igw_name            = "projectvpc-igw"
  public_rt_name      = "projectvpc-public-rt"
  private_rt_name     = "projectvpc-private-rt"
  nat_eip_name        = "projectvpc-nat-eip"
  nat_gateway_name    = "projectvpc-nat-gateway"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = local.public_subnet_name
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = local.private_subnet_name
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.igw_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.public_rt_name
    Tier = "public"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = local.nat_eip_name
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = local.nat_gateway_name
  }

  depends_on = [
    aws_internet_gateway.main,
    aws_route_table_association.public,
  ]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.private_rt_name
    Tier = "private"
  }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cloudhealth_account_id" {
  description = "AWS account ID of the CloudHealth SaaS platform account that is permitted to assume the cross-account role."
  type        = string
  default     = "123456789012"
}

variable "cloudhealth_external_id" {
  description = "Shared External ID that the assuming principal must present to satisfy the trust policy condition (confused-deputy mitigation). Never supplied by the assumed role itself."
  type        = string
  sensitive   = true
  default     = "CloudHealth-External-Id-Placeholder"
}

data "aws_partition" "current" {}

locals {
  cloudhealth_name = "CloudHealth-IAM-Role"

  common_tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
    Purpose     = "CloudHealth-Cost-Analysis"
  }
}

data "aws_iam_policy_document" "cloudhealth_assume_role_policy" {
  statement {
    sid    = "AllowCloudHealthAssumeRoleWithExternalId"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${var.cloudhealth_account_id}:root"
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.cloudhealth_external_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [var.cloudhealth_account_id]
    }
  }
}

resource "aws_iam_role" "cloudhealth_iam_role" {
  name                 = local.cloudhealth_name
  description          = "Cross-account role assumed by the CloudHealth SaaS platform for AWS cost and usage analysis."
  max_session_duration = 43200
  assume_role_policy   = data.aws_iam_policy_document.cloudhealth_assume_role_policy.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudhealth_cost_analysis_policy" {
  statement {
    sid    = "EC2ReadOnly"
    effect = "Allow"

    actions = [
      "ec2:Describe*",
      "ec2:Get*",
      "ec2:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancingReadOnly"
    effect = "Allow"

    actions = [
      "elasticloadbalancing:Describe*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "RDSReadOnly"
    effect = "Allow"

    actions = [
      "rds:Describe*",
      "rds:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "S3ReadOnly"
    effect = "Allow"

    actions = [
      "s3:Get*",
      "s3:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DynamoDBReadOnly"
    effect = "Allow"

    actions = [
      "dynamodb:Describe*",
      "dynamodb:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"

    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsReadOnly"
    effect = "Allow"

    actions = [
      "logs:Describe*",
      "logs:Get*",
      "logs:FilterLogEvents",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CostExplorerReadOnly"
    effect = "Allow"

    actions = [
      "ce:Describe*",
      "ce:Get*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CostAndUsageReportReadOnly"
    effect = "Allow"

    actions = [
      "cur:Describe*",
      "cur:Get*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "OrganizationsReadOnly"
    effect = "Allow"

    actions = [
      "organizations:Describe*",
      "organizations:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "IAMReadOnly"
    effect = "Allow"

    actions = [
      "iam:Get*",
      "iam:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CloudTrailReadOnly"
    effect = "Allow"

    actions = [
      "cloudtrail:Describe*",
      "cloudtrail:Get*",
      "cloudtrail:LookupEvents",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ECSReadOnly"
    effect = "Allow"

    actions = [
      "ecs:Describe*",
      "ecs:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EKSReadOnly"
    effect = "Allow"

    actions = [
      "eks:Describe*",
      "eks:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "LambdaReadOnly"
    effect = "Allow"

    actions = [
      "lambda:Get*",
      "lambda:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KMSReadOnly"
    effect = "Allow"

    actions = [
      "kms:Describe*",
      "kms:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ResourceGroupsTaggingReadOnly"
    effect = "Allow"

    actions = [
      "tag:GetResources",
      "tag:GetTagKeys",
      "tag:GetTagValues",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ServiceQuotasReadOnly"
    effect = "Allow"

    actions = [
      "servicequotas:Get*",
      "servicequotas:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "TrustedAdvisorReadOnly"
    effect = "Allow"

    actions = [
      "support:Describe*",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudhealth_iam_role" {
  name        = local.cloudhealth_name
  description = "Read-only describe, list and get permissions across AWS services for CloudHealth cost and usage analysis."
  policy      = data.aws_iam_policy_document.cloudhealth_cost_analysis_policy.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cloudhealth_iam_role" {
  role       = aws_iam_role.cloudhealth_iam_role.name
  policy_arn = aws_iam_policy.cloudhealth_iam_role.arn
}

output "cloudhealth_iam_role_arn" {
  description = "ARN of the cross-account IAM role that the CloudHealth SaaS platform assumes."
  value       = aws_iam_role.cloudhealth_iam_role.arn
}

output "cloudhealth_iam_policy_arn" {
  description = "ARN of the customer-managed CloudHealth read-only cost and usage analysis policy."
  value       = aws_iam_policy.cloudhealth_iam_role.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Static provider metadata (no pre-existing remote state lookups)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Name        = "endpoint-backup"
    Application = "endpoint-backup"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Customer managed KMS key for S3 default encryption (SSE-KMS)
###############################################################################

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer managed key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup-s3"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

###############################################################################
# S3 bucket (object lock intentionally left disabled: no
# aws_s3_bucket_object_lock_configuration resource is declared)
###############################################################################

resource "aws_s3_bucket" "endpoint_backup" {
  bucket        = local.bucket_name
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Bucket policy: enforce TLS 1.2+ and block over-long COMPLIANCE retention
###############################################################################

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyTlsVersionBelow12"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceRetentionOver90Days"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

###############################################################################
# IAM user (no access keys, no console login profile)
###############################################################################

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = local.common_tags
}

###############################################################################
# Customer managed least-privilege policy for bucket read/write access
###############################################################################

data "aws_iam_policy_document" "endpoint_backup_bucket_read_write_access" {
  statement {
    sid    = "BucketLevelRead"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
    ]
  }

  statement {
    sid    = "ObjectReadWriteDeleteRestore"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObjectLegalHold",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]
  }

  statement {
    sid    = "S3EncryptionKeyAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.endpoint_backup.arn,
    ]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Least-privilege read/write/version/retention/restore access to the endpoint-backup bucket and its encryption key."
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_read_write_access.json

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

