###############################################################################
# IAM role, policy and attachment for S3 replication
###############################################################################

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid    = "ReadSourceBucketConfiguration"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
    ]

    resources = [
      aws_s3_bucket.log1a.arn,
      aws_s3_bucket.log1b.arn,
      aws_s3_bucket.log2a.arn,
      aws_s3_bucket.log2b.arn,
    ]
  }

  statement {
    sid    = "ReadSourceObjectVersions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      "${aws_s3_bucket.log1a.arn}/*",
      "${aws_s3_bucket.log1b.arn}/*",
      "${aws_s3_bucket.log2a.arn}/*",
      "${aws_s3_bucket.log2b.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicateToDestinationBuckets"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = [
      "${aws_s3_bucket.log1a_replica1.arn}/*",
      "${aws_s3_bucket.log1b_replica1.arn}/*",
      "${aws_s3_bucket.log2a_replica1.arn}/*",
      "${aws_s3_bucket.log2b_replica1.arn}/*",
      "${aws_s3_bucket.log1a_replica2.arn}/*",
      "${aws_s3_bucket.log1b_replica2.arn}/*",
      "${aws_s3_bucket.log2a_replica2.arn}/*",
      "${aws_s3_bucket.log2b_replica2.arn}/*",
    ]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = ["kms:Decrypt"]

    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
  }

  statement {
    sid    = "EncryptReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-replication-policy"
  description = "Least-privilege policy allowing S3 cross-region replication"
  policy      = data.aws_iam_policy_document.s3_replication.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Replication configurations
###############################################################################

resource "aws_s3_bucket_replication_configuration" "log1a" {
  bucket = aws_s3_bucket.log1a.id
  role   = aws_iam_role.replication.arn

  rule {
    id       = "replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica1.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica2.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.log1a,
  ]
}

